quests[27989] = { id = 27989, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruumbo Demands Honey", description = "Ruumbo hungers!\n\nThe Deadwood jerks have stolen all their honey from the Timbermaw tribe! We saw...er, Ruumbo saw them do it! Now Ruumbo must have that honey!\n\nTake this... this stick! Yes, this stick. Take this stick and use it to steal the honey from their beehives in Deadwood Village.\n\nRuumbo must have as much honey as possible. This is vital.", progress = "Ruumbo can smell whether you have honey or not!", completion = "Honey! Delicious honey!\n\nWell done, ugly creature! You may put the honey...put the honey down right there. No, to the left. Yes, there. Just leave it there.", objectives = "Collect 10 Deadwood Honey Globs from the hives in Deadwood Village using Ruumbo's Honey Stick.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27990] = { id = 27990, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battlezone", description = "It vould appear zhat anozher opportunity has arisen for you to redeem yourself, {race}.\n\nZhis little emergency has set me back a few tank gunnahs.\n\nYou zhink you have vhat it takes to fill in for vone of zhem?\n\nMy tanks are just vest of zhe camp. Get out zhere and put an end to zhis silliness!", completion = "Auch!\n\nIf I vere an inch or two taller, I'd be dead!", objectives = "Commander Schnottz wants you to man one of the siege tank turrets and use it to defeat 7 Decrepit Watchers, then report back to him.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27991] = { id = 27991, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taking the Overlook Back", description = "There is only one way for us to take Largo's Overlook back.\n\nI think you know what we need to do {name}.  Largo is pretty paranoid these days so you should be able to find him on top of the tower, looking for his imaginary navy to finally arrive.", completion = "Ha, we finally got Largo!  Nice one, {name}.", objectives = "Sergeant Gray has asked you to kill Commander Largo at Largo's Overlook. The overlook is just northeast of the base camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27992] = { id = 27992, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magnets, How Do They Work?", description = "Getting useful machine parts out here on the island has been difficult, {name}.  We have been trying to repair the broken siege engines here in camp but we keep running out of useful parts.\n\nOur second regiment reported some wrecked out siege engines in a old battlefield to the west.  Maybe we could find some parts over there?\n\nYou are going to have trouble finding anything in that old battlefield so take this magnetized scrap collector and put it to some good use.", progress = "Did that magnet contraptaion actually work?", completion = "These parts will really help us out, {name}!  Who would have thought you can find stuff this useful in all that old junk?", objectives = "You have been tasked with recovering 7 pieces of Siege Engine Scrap. Use the Magnetized Scrap Collector in The Restless Front to find the scraps. The Restless Front is due west, just past the second bridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27993] = { id = 27993, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Take it to 'Em!", description = "We was lucky to escape, {class}. I'm not sure I'd feel right if we didn't take care of them ambushers.\n\nHows about you git back up to Khartut's tomb and give them little buggers what fer!\n\nIt's off to the northeast, just inside the entrance to Uldum if'n I recollect correctly.\n\nWhat're you looking at? I sure ain't in no condition to do it!", completion = "Good to see ya, kid.\n\nWould've been even better if you'd have been here to help me take care of these little savages...", objectives = "Mack wants you to investigate Khartut's Tomb.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27994] = { id = 27994, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruumbo Demands Justice", description = "You! Wanderer! Bow before the might of Ruumbo, great god of the Timbermaw tribe!\n\nHear my will! The evil Deadwood tribe lives in the village behind me! They are big jerks!\n\nI mean, they... they sully my name with their wicked misdeeds! They persecute my cherished Timbermaw tribe and hurt them!\n\nI demand you inflict my justice! Defeat the Deadwood and I will give you my... my favor! Yes! The favor of RUUMBO!", completion = "It worked!\n\nI mean, uh, YES, the will of Ruumbo has been carried out! You have done well, creature! You may have these shiny coins!", objectives = "Slay 15 Deadwood Furbolg of any type.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27995] = { id = 27995, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dance for Ruumbo!", description = "You have done well, {race}! Ruumbo is pleased by your bravery, and the delicious honey you have given Ruumbo.\n\nNow, you must... you must dance! Yes!\n\nDance for Ruumbo! Dance!", completion = "Those two brats... I should have known! They were smart enough to hush whenever I went to examine the totem.\n\nI'll be sure to find them and drag them back to Timbermaw Hold by the ears! Thank you for looking into it...", objectives = "Do a silly dance for Ruumbo.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27996] = { id = 27996, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orders Are For the Living", description = "Unsurprisingly, we aren't going to listen to Cromush about the plague. However, his brute strength will come in handy for muscling my men through the many foes ahead on the path to Godfrey, the most powerful being his right hand man, Lord Walden.\n\nI'll meet you in Walden's chamber after you finish him off. Then, at long last, we can completely take Shadowfang Keep for the Forsaken!", progress = "You have your orders, {name}.", completion = "The time has come! Godfrey will fall!", objectives = "Kill Lord Walden.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27997] = { id = 27997, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Corruption of the Jadefire", description = "The cleansing of this forest has been a grueling process. For every success we have achieved, a new challenge has arisen.\n\nThe Jadefire satyr have been a constant nuisance. They seek to corrupt the forest just as we seek to cleanse it. Now, we have taken steps to begin eradicating them from Felwood entirely.\n\nTravel to Jadefire Glen to the west and rid the forest of their presence. You'll find the entrance just north of the walls of Deadwood Village; look for their vile banners.", progress = "Jadefire Glen is our first target in a series of coordinated efforts. The others will be dealt with in time.", completion = "The Emerald Circle thanks you, {name}. If we all work together here, we can purge these demons from our midst.", objectives = "Slay 12 Jadefire Satyr or Jadefire Felsworn in Jadefire Glen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27998] = { id = 27998, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sweet, Merciless Revenge", description = "If all goes well you'll just be able to walk right into Godfrey's personal domain and take a reward fitting for such an eager young {class}.\n\nGodfrey is a cunning foe, though, so it may be wise to head up there quickly just in case you're needed. He will pay for what he did to the Dark Lady!", progress = "Let's get going.", completion = "For a moment there, I thought all was lost. Even when surrounded by the worgen in Gilneas I had higher hopes!\n\nBut you proved me wrong {name}. I will see to it that Sylvanas herself hears of your triumph here today. Don't worry about the mess here, I will gladly see to it myself.", objectives = "Kill Lord Godfrey.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27999] = { id = 27999, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fate of the Doyles", description = "It seems the Doyles already joined their last fight. Iain will want to know of their fate.", completion = "That's a right shame. Stubborn as they were to speak to, they were just as stubborn in a fight. Would have been good to have 'em.\n\nOnce this is done, we'll have to send some boys out to bring them back for a proper send off.", objectives = "Return the news of Clan Doyle to Iain Firebeard at the Firebeard Cemetery.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28000] = { id = 28000, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Do the Imp-Possible", description = "The satyr hide their corrupted moonwell behind an impenetrable barrier of demonic fire. Their forces must have some way of getting through it.\n\nInterrogating the satyr will be useless, but the imps they consort with will be easily swayed. I have a specific one in mind, as well...\n\nIn the foothills to the east, a lone imp has been seen wandering, far from the other demons. He should prove easy pickings. Weaken him with combat, and then use this enchanted sack to capture him. Then I'll do the talking...", progress = "Do you have an imp for me?", completion = "Imps are creatures of deception. With so many of them spotted at Shadowlurk Ridge, I'm positive something is being hidden there.\n\nOur little friend will tell us exactly how to find it... if he doesn't want to go back in the sack.", objectives = "Weaken Impsy and use the Enchanted Imp Sack to capture him.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28001] = { id = 28001, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Coward's Due", description = "We may be safe here, but there are a lot of Wildhammer who could still use support. Our wing can offer that, but we need to keep bolsterin' our forces if we're going to clear the Twilight completely.\n\nI'm going to have words with Colin Thundermar. Only a coward turns down the callin' of his people, especially in a time this dire.\n\nGo to Thundermar, find Colin and get a real explanation out of'm. I won't be putting up with cowardice in a Wildhammer leader.", completion = "Here here, WOT!? He calls ME a COWARD!?\n\nJust like a Firebeard, all hot air and not a lick of sense. I've been bearing the brunt of a Dragonmaw invasion from the south, much of Thundermar is in ruins, and do any of the other clans stick up to help? NO! Ol' Thundermar is on his own he is, and you'd better believe I'm usin' everything in my arsenal just to stem the tide.", objectives = "Speak to Colin Thundermar in Thundermar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28002] = { id = 28002, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crisis Management", description = "There is a delicate situation that calls for the... objective discretion of an outsider.\n\nYou see, an unfortunate incident has upset some of our guests. Rest assured, our top men are sorting out the details.\n\nIn the meantime, it would be wonderful if you could calm our more squeamish visitors.\n\nHandle this well, and the furrier is sure to hear of it!", completion = "Hmm, still a bit frazzled, are they?\n\nWell, you know what they say. Time heals all wounds.\n\nExcept for those of the ambassador, of course...", objectives = "Belloc Brightblade wants you to reassure the guests at Schnottz's Landing.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28003] = { id = 28003, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Ragefire Chasm", description = "The Warchief has requested that any able-bodied adventurer head to Ragefire Chasm, just beneath the great city of Orgrimmar, immediately!\n\nThe Searing Blade is poised to launch an attack at any moment and the city guards cannot hold for much longer! If you so choose, head to Ragefire Chasm and speak with Stone Guard Kurjack, head of the defense initiative, to end the threat to Orgrimmar once and for all.", sourceObjective = "Speak with Stone Guard Kurjack.", sourceObjectiveStatus = "unverified-source-field" }
quests[28004] = { id = 28004, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: The Deadmines", description = "The Warchief has requested that any able-bodied adventurer head to the Deadmines, in the distant land of Westfall, immediately!\n\nAssistance is required in the initiative to take the Defias Juggernaut for the Horde to use against the Alliance! If you so choose, head to the Deadmines and speak with Kagtha, a rogue of the Shattered Hand, to aid in the ongoing war against the Alliance.", sourceObjective = "Speak with Kagtha.", sourceObjectiveStatus = "unverified-source-field" }
quests[28005] = { id = 28005, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: The Deadmines", description = "King Anduin Wrynn has requested that any able-bodied adventurer head to the Deadmines, in southern Westfall, immediately!\n\nAssistance is required in stopping the reborn Defias Brotherhood from terrorizing the area! If you so choose, head to the Deadmines and speak with Lieutenant Horatio Laine, lead investigator on the case, to aid in stopping the Defias once and for all.", sourceObjective = "Speak with Lieutenant Horatio Laine.", sourceObjectiveStatus = "unverified-source-field" }
quests[28006] = { id = 28006, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Wailing Caverns", description = "The Warchief has requested that any able-bodied adventurer head to the Wailing Caverns, just west of the Crossroads, immediately!\n\nNaralex must be awakened to save the Barrens! If you so choose, head to the Wailing Caverns and speak with Nalpak, one of Naralex's disciples, to help in healing the injured land.", sourceObjective = "Speak with Nalpak.", sourceObjectiveStatus = "unverified-source-field" }
quests[28007] = { id = 28007, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Wailing Caverns", description = "King Anduin Wrynn has requested that any able-bodied adventurer head to the Wailing Caverns, just west of the Crossroads, immediately!\n\nNaralex must be awakened to save the Barrens! If you so choose, head to the Wailing Caverns and speak with Nalpak, one of Naralex's disciples, to help in healing the injured land.", sourceObjective = "Speak with Nalpak.", sourceObjectiveStatus = "unverified-source-field" }
quests[28008] = { id = 28008, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Shadowfang Keep", description = "The Warchief has requested that any able-bodied adventurer head to Shadowfang Keep, in southern Silverpine Forest, immediately!\n\nThe traitor, Lord Godfrey, must pay for what he did to Sylvanas! If you so choose, head to Shadowfang Keep and speak with Deathstalker Commander Belmont, leader of the war effort there, to help enact proper revenge.", sourceObjective = "Speak with Deathstalker Commander Belmont.", sourceObjectiveStatus = "unverified-source-field" }
quests[28009] = { id = 28009, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Shadowfang Keep", description = "King Anduin Wrynn has requested that any able-bodied adventurer head to Shadowfang Keep, in southern Silverpine Forest, immediately!\n\nThe traitor, Lord Godfrey, must pay for what he did to our new allies! If you so choose, head to Shadowfang Keep and speak with Packleader Ivar Bloodfang, leader of the war effort there, to help enact proper revenge.", sourceObjective = "Speak with Packleader Ivar Bloodfang.", sourceObjectiveStatus = "unverified-source-field" }
quests[28010] = { id = 28010, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Blackfathom Deeps", description = "The Warchief has requested that any able-bodied adventurer head to Blackfathom Deeps, north of Zoram'gar Outpost, immediately!\n\nThe Twilight's Hammer threatens the world with its actions there! If you so choose, head to Blackfathom Deeps and speak with Je'neu Sancrea, a member of the Earthen Ring, to help stop the Twilight threat.", sourceObjective = "Speak with Je'neu Sancrea.", sourceObjectiveStatus = "unverified-source-field" }
quests[28011] = { id = 28011, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Blackfathom Deeps", description = "King Anduin Wrynn has requested that any able-bodied adventurer head to Blackfathom Deeps, west of Astranaar, immediately!\n\nThe Twilight's Hammer threatens the world with its actions there! If you so choose, head to Blackfathom Deeps and speak with Sentinel Aluwyn, head of the night elf effort there, to help stop the Twilight threat.", sourceObjective = "Speak with Sentinel Aluwyn.", sourceObjectiveStatus = "unverified-source-field" }
quests[28012] = { id = 28012, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Stormwind Stockade", description = "King Anduin Wrynn has requested that any able-bodied adventurer head to the Stormwind Stockade, inside his highness' own city, immediately!\n\nA mass riot has begun within! If you so choose, head to the Stockade and speak with Rifle Commander Coe, head rifleman of the Stockade guard, to help quell the uprising.", sourceObjective = "Speak with Rifle Commander Coe.", sourceObjectiveStatus = "unverified-source-field" }
quests[28013] = { id = 28013, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Gnomeregan", description = "King Anduin Wrynn has requested that any able-bodied adventurer head to Gnomeregan,west of Ironforge, immediately!\n\nThe Gnomes need help reclaiming their city! If you so choose, head to Gnomeregan and speak with Murd Doc, recruiter for the G-Team, to help in the mission.", sourceObjective = "Speak with Murd Doc.", sourceObjectiveStatus = "unverified-source-field" }
quests[28014] = { id = 28014, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Razorfen Kraul", description = "King Anduin Wrynn has requested that any able-bodied adventurer head to Razorfen Kraul, in the southernmost part of the Southern Barrens, immediately!\n\nAuld Stonespire needs assistance in stopping the quilboar before they begin to spread further! If you so choose, head to Razorfen Kraul and speak with Auld Stonespire, a wise and respected shaman, to help stop the menace.", sourceObjective = "Speak with Auld Stonespire.", sourceObjectiveStatus = "unverified-source-field" }
quests[28015] = { id = 28015, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Razorfen Kraul", description = "The Warchief has requested that any able-bodied adventurer head to Razorfen Kraul, in the southernmost part of the Southern Barrens, immediately!\n\nAuld Stonespire needs assistance in stopping the quilboar before they begin to spread further! If you so choose, head to Razorfen Kraul and speak with Auld Stonespire, a wise and respected shaman, to help stop the menace.", sourceObjective = "Speak with Auld Stonespire.", sourceObjectiveStatus = "unverified-source-field" }
quests[28016] = { id = 28016, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Scarlet Monastery Graveyard", description = "The Warchief has requested that any able-bodied adventurer head to the Scarlet Monastery Graveyard, northeast of the Undercity, immediately!\n\nDark Ranger Velonara has requested more soldiers to help her begin her assault! If you so choose, head to the Scarlet Monastery Graveyard and speak with Dark Ranger Velonara, a clever fighter indeed, to do your part.", sourceObjective = "Speak with Dark Ranger Velonara.", sourceObjectiveStatus = "unverified-source-field" }
quests[28017] = { id = 28017, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Scarlet Halls", description = "The Warchief has requested that any able-bodied adventurer head to the Scarlet Halls, northeast of the Undercity, immediately!\n\nCrusader activity has picked up throughout the plaguelands and elsewhere. The Warchief believes a revival is underway, and this will NOT be tolerated.\n\nEnter the Scarlet Halls to crush their armory and lay waste to their library before they can mobilize.", objectives = "Enter the Scarlet Halls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28018] = { id = 28018, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Scarlet Monastery Armory", description = "The Warchief has requested that any able-bodied adventurer head to the Scarlet Monastery Armory, northeast of the Undercity, immediately!\n\nDark Ranger Velonara has requested more soldiers to help her take out their offensive capabilities! If you so choose, head to the Scarlet Monastery Armory and speak with Dark Ranger Velonara to do your part.", sourceObjective = "Speak with Dark Ranger Velonara.", sourceObjectiveStatus = "unverified-source-field" }
quests[28019] = { id = 28019, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Scarlet Monastery", description = "The Warchief demands that able-bodied adventurers assault the Scarlet Monastery, northeast of the Undercity, immediately!\n\nThe Scarlet Crusade has continually threatened Forsaken strongholds throughout the plaguelands. They MUST be destroyed.\n\nReport to the Scarlet Monastery to execute the Warchief's orders and crush the crusade once and for all.", objectives = "Enter the Scarlet Monastery.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28020] = { id = 28020, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Scarlet Monastery Graveyard", description = "King Varian Wrynn has requested that any able-bodied adventurer head to the Scarlet Monastery Graveyard, northeast of the Undercity, immediately!\n\nJoseph the Awakened, a former crusader, has requested aid to help him take out the leaders there and reform the crusade! If you so choose, head to the Scarlet Monastery Graveyard and speak with Joseph the Awakened to do your part.", sourceObjective = "Speak with Joseph the Awakened.", sourceObjectiveStatus = "unverified-source-field" }
quests[28021] = { id = 28021, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Scarlet Halls", description = "King Anduin Wrynn has requested that any able-bodied adventurer head to the Scarlet Halls, northeast of the Undercity, immediately!\n\nCrusader activity has picked up throughout the plaguelands and elsewhere. His majesty fears a revival is underway. Scarlet zealotry will not be tolerated near the King's lands!\n\nEnter the Scarlet Halls and assault the armory and library before they can mobilize.", objectives = "Enter the Scarlet Halls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28022] = { id = 28022, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Scarlet Monastery Armory", description = "King Varian Wrynn has requested that any able-bodied adventurer head to the Scarlet Monastery Armory, northeast of the Undercity, immediately!\n\nJoseph the Crazed has requested help to kill Herod, the Scarlet Champion! If you so choose, head to the Scarlet Monastery Armory and speak with Joseph the Crazed to help him out.", sourceObjective = "Speak with Joseph the Crazed.", sourceObjectiveStatus = "unverified-source-field" }
quests[28023] = { id = 28023, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Scarlet Monastery", description = "King Anduin Wrynn has requested able-bodied adventurers to assault the Scarlet Monastery, northeast of the Undercity, immediately!\n\nRepeated efforts to negotiate with the Scarlet Crusade have failed. Their zealotry is wreaking havoc across the reclaimed plaguelands and elsewhere.\n\nReport to the Scarlet Monastery to dish out the King's justice. Use of deadly force is encouraged!", objectives = "Enter the Scarlet Monastery.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28024] = { id = 28024, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Razorfen Downs", description = "King Anduin Wrynn has requested that any able-bodied adventurer head to Razorfen Downs, in Thousand Needles, immediately!\n\nThe mysterious Koristrasza needs help to stop the Scourge-Quilboar alliance! If you so choose, head to Razorfen Downs and speak with Koristrasza to lend her your skills.", sourceObjective = "Speak with Koristrasza.", sourceObjectiveStatus = "unverified-source-field" }
quests[28025] = { id = 28025, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Razorfen Downs", description = "The Warchief has requested that any able-bodied adventurer head to Razorfen Downs, in Thousand Needles, immediately!\n\nThe mysterious Koristrasza needs help to stop the Scourge-Quilboar alliance! If you so choose, head to Razorfen Downs and speak with Koristrasza to lend her your skills.", sourceObjective = "Speak with Koristrasza.", sourceObjectiveStatus = "unverified-source-field" }
quests[28026] = { id = 28026, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Uldaman", description = "The Warchief has requested that any able-bodied adventurer head to Uldaman, near New Kargath, immediately!\n\nThe Reliquary and its leader, High Examine Tae'thelan Bloodwatcher, requires assistance in obtaining powerful relics within! If you so choose, head to Uldaman and speak with the High Examiner to aid their cause.", sourceObjective = "Speak with High Examiner Tae'thelan Bloodwatcher.", sourceObjectiveStatus = "unverified-source-field" }
quests[28027] = { id = 28027, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Uldaman", description = "King Anduin Wrynn has requested that any able-bodied adventurer head to Uldaman, in the Badlands, immediately!\n\nThe Explorers' League, under Lead Prospector Durdin, requires assistance in braving great danger in pursuit of knowledge! If you so choose, head to Uldaman and speak with Lead Prospector Durdin to help them out.", sourceObjective = "Speak with Lead Prospector Durdin.", sourceObjectiveStatus = "unverified-source-field" }
quests[28028] = { id = 28028, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siege!", description = "That Overseer Oilfist couldn't'a picked a worse time to ask me to join a fight.  My summit's already under siege!\n\nIt's nothin' my guards can't handle, but still, it won't be easy for me to just pick up and send some dwarves into that infernal gorge.\n\nTell ya what: you take out their marksmen that're holding our fortress under siege, and I'll consider your offer.  Ye'll find 'em slinkin' around the flats to the east.", completion = "If nothin' else, you bought us some time, and some room to open up our supply lines through this siege.\n\nYer a fine {class}.", objectives = "Slay 9 Dark Iron Marksmen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28029] = { id = 28029, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Set Them Ablaze!", description = "I'm not sure if ye've noticed, but my tower's much taller than any o' the other towers here around the Gorge.  Some dwarves pride themselves at how deep they can dig, but not me.  Sometimes I think I shoulda been born a Wildhammer.\n\nI still don't like the sight o' those other towers, though.  Reachin' up like that, ticklin' my tower's feet.  Here, take this torch, an' use it on the braziers atop those other towers.  They'll be sorry they ever built 'em to begin with.", completion = "Looks like ye know how to light things on fire!  An admirable trait in any {race}, for sure.", objectives = "Use the Torch of Retribution on the four towers surrounding the Cauldron.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28030] = { id = 28030, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They Build a Better Bullet", description = "Those gorge-digging dwarves do at least one thing right: they make very high-quality bullets.  I've been unable to reproduce their results, so I've taken to stealing whatever bullets of theirs that I can find.\n\nYe want my help?  Get me a couple hundred bullets from those marksmen below.\n\nI'm sure they'll be happy to give ye their bullets one at a time, but you might find it faster just to look for the crates filled with them.", progress = "A real {class} woulda caught the bullets with his teeth.", completion = "I'll just divvy these up amongst the guards.  Ye have my thanks.", objectives = "Obtain 200 Dark Iron Bullets.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28031] = { id = 28031, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Special Delivery for Brivelthwerp", description = "I have a new business partner, my best buddy, Brivelthwerp. Even as we speak, he's building up the infrastructure for our new ice cream empire!\n\nHe took our coolant tug, inventory, and employees southwest to the Sunken Dig Site. Unfortunately, I don't currently have a way to deliver something to him... something extremely important: our super-secret I-Scream Cryocannon!\n\nYou don't mind taking it to him, do you, {name}?", progress = "That's not what I think it is? Is it?!", completion = "That must be the new I-Scream Cryocannon! Ain't she a beauty?!\n\n<Brivelthwerp eyes you shrewdly.>\n\nI'm going to let you in on a secret, my good friend: the groundwork for a vast mercantile empire is being laid right here!\n\nTell me... how do you feel about ice cream?", objectives = "Deliver the I-Scream Cryocannon to Brivelthwerp at the Sunken Dig Site in Thousand Needles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28032] = { id = 28032, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mysteries of the Fire-Gizzard", description = "There's so much we don't know about the incendosaurs.  Where did they come from?  How do they survive out here on the flats?  And why do they taste so bad?\n\nThe key to understanding these prehistoric beasts, I believe, starts with the fire-gizzard.  Every incendosaur has one.  I'd like a few of them to study.\n\nYou'll find incendosaurs circling the foot of Iron Summit, mostly to the west.", progress = "I'm finally getting my hands on those lizard gizzards!", completion = "Ooh, these are nice.  Now, leave me alone with my gizzards.  I've got studying to do!\n\n<Agnes starts to poke the gizzards with a stick.>\n\nYes, very interesting.  Very interesting indeed...", objectives = "Obtain 6 Fire-Gizzards.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28033] = { id = 28033, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deceit", description = "What?  Why're you still here?  Oh, did I promise that I'd help you and the Thorium Brotherhood in yer fight?\n\nI lied.\n\nI just can't spare the men right now.  I know I said I'd help, but there's absolutely no way you can convince me to leave Iron Summit right now.  Absolutely no way.", completion = "Well well well.  Look who come searching for Lunk this time!\n\nThis sounds like case for Lunk's unique brand of no-kill problem-solve.", objectives = "Find a way to convince Mountain-Lord Rendan to join the Thorium Brotherhood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28034] = { id = 28034, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lunk's Adventure: Rendan's Weakness", description = "Lunk not smart, but Lunk notice things.  Today, Lunk notice that Mountain-Dwarf likes to watch people dance.\n\nLunk like to dance!  {name} like to dance!  Probably!\n\nMaybe we find some more dwarfs that like to dance.  Then we go talk to Mountain-Dwarf, and he will listen to {name}.", completion = "Did I stutter?  I believe I clearly stated that I... won't...\n\nWow, ye've got some good moves there!  I'm impressed!", objectives = "Speak with three Iron Summit Guards and ask them to join your dance.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28035] = { id = 28035, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mountain-Lord's Support", description = "Alright, alright!  If I knew ye could dance like that, I wouldn't'a asked ye to do all that stuff earlier.\n\nTell Overseer Oilfist that I'll be joinin' ye.  I'll meet ye in the slag pit, <lad/lass>!  With the combined forces of Thorium Point and Iron Summit, those gorge-dwarves won't know what hit 'em!", completion = "So, Rendan's on our side?  About time that oaf came around.\n\nLet's get moving, then.", objectives = "Report your success to Overseer Oilfist at Thorium Point in Searing Gorge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28036] = { id = 28036, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Zul'farrak", description = "King Anduin Wrynn has requested that any able-bodied adventurer head to Zul'farrak, just west of Gadgetzan, immediately!\n\nGadgetzan is being threatened by the Sandfury trolls and their growing army! If you so choose, head to Zul'farrak and speak with Tran'rek to help the goblins out.", sourceObjective = "Speak with Tran'rek.", sourceObjectiveStatus = "unverified-source-field" }
quests[28037] = { id = 28037, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Zul'farrak", description = "The Warchief has requested that any able-bodied adventurer head to Zul'farrak, just west of Gadgetzan, immediately!\n\nGadgetzan is being threatened by the Sandfury trolls and their growing army! If you so choose, head to Zul'farrak and speak with Tran'rek to help the goblins out.", sourceObjective = "Speak with Tran'rek.", sourceObjectiveStatus = "unverified-source-field" }
quests[28038] = { id = 28038, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood in the Highlands", description = "You've got some fight in you, {class}. You might do well in the crucible.\n\nWhat!? You haven't heard of the Crucible of Carnage? That smarmy goblin Gurgthock and his troll sidekick have been plastering us with leaflets ever since he set up shop here in the Highlands. Champions from all over Azeroth fight to the death in there. You should gather up some friends and see how you fare.\n\nThe Crucible is just to the southwest. Look for Wodin the Troll-Servant somewhere in the middle of a ring of bones.", completion = "Hey, you're one big strong heap of {class}. Can you handle the crucible? We got bookies are standing by!", objectives = "Talk to Wodin the Troll-Servant at the Crucible of Carnage in Twilight Highlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28039] = { id = 28039, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Maraudon", description = "The Warchief has requested that any able-bodied adventurer head to Maraudon, in western Desolace, immediately!\n\nHealing Maraudon from its current corruption would great help the entirety of Desolace! If you so choose, head to Maraudon and speak with Zaetar's Spirit, he will guide you.", sourceObjective = "Speak with Zaetar's Spirit.", sourceObjectiveStatus = "unverified-source-field" }
quests[28040] = { id = 28040, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Maraudon", description = "King Anduin Wrynn has requested that any able-bodied adventurer head to Maraudon, in western Desolace, immediately!\n\nHealing Maraudon from its current corruption would great help the entirety of Desolace! If you so choose, head to Maraudon and speak with Zaetar's Spirit, he will guide you.", sourceObjective = "Speak with Zaetar's Spirit.", sourceObjectiveStatus = "unverified-source-field" }
quests[28041] = { id = 28041, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bait and Throttle", description = "You can hold your own on the ground, {name}. I'll give you that.\n\nBut we Dragonmaw dominate the skies as well as land. Until you can prove to me you can handle a drake as well as a Dragonmaw, your Horde is nothing to me.\n\nLet's see if you can wrangle one back to Bloodgulch.\n\nFirst you'll need bait. Go out and kill one of the gryphons that wander the woods west or northeast of here. Make sure it's untamed! Drakes hate the stink of dwarf on their food.\n\nGet the gryphon carcass and you'll know what to do.", progress = "<You gather up the fresh carcass.>", completion = "<You gather up the fresh carcass.>", objectives = "Get a Fresh Gryphon Carcass.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28042] = { id = 28042, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Special Delivery for Brivelthwerp", description = "I recently came into possession of something that needs to be delivered to a gnome that goes by the name, Brivelthwerp. It's more like Briveltwerp if you ask me.\n\nI want you to take it to him in the southwest, down at the Sunken Dig Site. He's up to something and there's moolah involved... I can smell it!\n\nKeep an eye on what he's doing, {name}, and see if you can't get a cut of his profits. A big cut!", progress = "That's not what I think it is? Is it?!", completion = "<Brivelthwerp eyes you up and down, but becomes overjoyed at the site of the special delivery.>\n\nWelcome, friend, welcome! I'm going to give you the chance to get involved at the ground level of a once-in-a-lifetime opportuntity.\n\nThe entrepreneurial spirit knows nothing of the differences between the Alliance and the Horde!\n\nTell me... how do you feel about ice cream?", objectives = "Deliver the I-Scream Cryocannon to Brivelthwerp at the Sunken Dig Site in Thousand Needles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28043] = { id = 28043, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "How to Maim Your Dragon", description = "<You sling the gore-spattered gryphon corpse over your shoulder, its wings dragging to the ground.>\n\n<Highland Black Drakes roost just southwest of the Crucible of Carnage, along a ring of low mountain peaks.>\n\n<If you drop the gryphon corpse there, a drake is sure to start feeding. With its guard down, you should be able to attack it until it is weak enough to mount and fly.>", completion = "That was an impressive aerial display, {name}, but I wish it had come at a better time.\n\nNarkrall is a great warrior, but he's also an impatient fool. He's about to get himself killed ... and we're about to lose one of our most important weapons in the battle for the Highlands!", objectives = "Lure in a Baited Black Drake, attack it until it is weak, and then ride it back to Bloodgulch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28044] = { id = 28044, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Touch the Untouchable", description = "I've added a drop of my very own essence to the ooze. Look for a glowing sigil to the west, at the edge of Shadowlurk Ridge. Stand on it, concentrate, and pour this stuff all over yourself. It should be enough to shift you into the nether and let you see what's REALLY there.\n\nYou won't be alone... the satyr's treasure is being guarded by the biggest voidstalker they could summon. Defeat him, and the treasure is yours.\n\nAnd come back in one piece, or this crazy broad's gonna fry me!", progress = "Can you hear me in there, {name}? Do you have the claw?", completion = "The Claw of Tichondrius...\n\nYou hold a piece of the very demon that led the Legion to these woods, {name}. Better for it to be in our hands than with the satyr.\n\nHold still. I'm going to pull you back to our plane and make sure you and the claw arrive here safely...", objectives = "Use the Phaseblood Potion at the Sigil of Tichondrius to shift into the nether, and search for the Claw of Tichondrius.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28045] = { id = 28045, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Greatest Flavor in the World!", description = "Below us is a cave. It's huge! The perfect location for our new refrigerated vault. It's big enough to hold all of our inventory with room to grow.\n\nUnfortunately, when we were almost done equipping all of the pipes, bugs burrowed up out of nowhere and killed all of my employees!\n\nHow was I supposed to know?\n\nBut it gave me a great idea: silithid-flavored ice cream. We'll make a killing!\n\nAll I need now are the ingredients.", progress = "You got enough bug goo for the first batch?", completion = "Oh yeah! This is going to be the greatest flavor in the world!\n\nLook out, Tigule and Foror!!!", objectives = "Collect 8 Scoops of Silithid Goo.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28046] = { id = 28046, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finish The Job", description = "We have been trying to collect useful scraps from the front all week.  Every time we gather a batch to bring back to camp, we get assaulted by the restless infantry in the area.  Can you head over there and clear them out?", completion = "It's about time someone took those guys out.", objectives = "Kill 5 Restless Infantry at the Restless Front. You can find the front on the west side of the island, just before Forgotten Hill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28047] = { id = 28047, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freezing the Pipes", description = "It's time to break out the I-Scream Cryocannon!\n\nWe lifted the tech from the frost cannons on the river boats. If it's one thing that we gnomes are good at, it's miniaturization by way of making everything else that much bigger!\n\nI need you to take the cannon down there into the cave and freeze the pipes we setup in the walls. That'll jumpstart them.", completion = "Do you hear that, {name}? That's the sweet hum of the refrigeration kicking in.\n\nWe'll be able to store our inventory down there in no time. Thank you!", objectives = "Use the I-Scream Cryocannon to freeze the four pipes inside the cave.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28048] = { id = 28048, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "That Smart One's Gotta Go", description = "There's some kind of smart brain bug in the back of the cave. It's in charge of all of the silithid down there.\n\nMy ice cream is melting! How am I supposed to launch my ice cream empire, and save my inventory, if that thing's in there?!", completion = "Outstanding! Nothing can stop us from being the greatest purveyors of ice cream in all of Azeroth!", objectives = "Slay the Hive Controller.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28049] = { id = 28049, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "See the Invisible", description = "Yeah, yeah, your stuck-up mage friend there hit it on the nose. The imps over at Shadowlurk Ridge are hiding the key to the satyr's barrier in the nether. It's right there, but you can't see it or touch it unless you're shifted.\n\nI guess you're out of luck though, because only imps can phase shift! So you should just close your eyes, turn around, and let me go...\n\nIt was just a joke! Don't hurt me! I'll need slime from the cursed oozes around these ruins. Bring me enough to cover you from head to toe!", progress = "You got that slime?", completion = "Oh good, you're back! Don't leave me alone with her! She's crazy!\n\nGimme that, I'll have you seeing the invisible in no time!", objectives = "Collect 8 batches of Cursed Ooze from the Ruins of Constellas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28050] = { id = 28050, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shark Tank", description = "I hate sharks.  All of my troops hate sharks too.  This is where you come in, {name}.\n\nI need you to head up to the Cape of Lost Hope and take out a huge shark named Tank.  Tank is not to be trifled with so I would bring a few friends if I were you.", completion = "No way, you actually killed him?  We are having shark tacos tonight for sure!", objectives = "You have been tasked to kill Tank, a large shark cruising the waters of the Cape of Lost Hope. The cape can be found north of here, along the northern coastline.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28051] = { id = 28051, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We All Scream for Ice Cream... and then Die!", description = "Don't get me wrong... I'm cheerful on the outside, but inside I'm just terribly torn to pieces. All of my friends and employees are dead.\n\nCould you do me a favor? Would you swim down there and attach the tug's tow hook to my dead employees? I'll reel them in.", completion = "Thank you, {name}. They gave their lives for ice cream.", objectives = "Attach the tug's tow hook to 10 Dead Employees.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28052] = { id = 28052, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Operation: Stir the Cauldron", description = "I'm putting you on a flying machine, {name}.\n\nYou'll be responsible for softening our landing into the slag pit.  Speak with your flight master here in Thorium Point, then fly down to the gorge.\n\nOnce you near your landing point, there will undoubtedly be hordes of Dark Iron dwarves waiting for you.  Use our flying machine's guns to take out as many of them as you can, then land at the cavern's entrance.  Rendan should be waiting for you by the time you arrive.", completion = "Well, here we are.\n\nI hope you're ready, {name}.", objectives = "Speak to the Thorium Point flight master, then use the Brotherhood Flying Machine's guns to kill Cauldron Defenders until the area is safe for entry.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28053] = { id = 28053, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lunk Like Your Style", objectives = "Lunk heared that you used the stone to banish fire-lizard.  You saved Gorge, and you didn't even kill!\n\nLunk so proud.  Lunk happy to be {name}'s teacher.\n\nMaybe you take this.  Lunk doesn't need it.  Lunk too busy adventuring!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28054] = { id = 28054, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slavery is Bad", description = "Much like Overseer Maltorius, I'm a rich dwarf.  However, I earned my riches through hard work and wise decisions, not through slavery.\n\nOK fine, very little slavery.  Hardly any.\n\nAnyhow, the first thing that I see inside these caverns are slavedrivers and taskmasters.  I won't stand for this!  As you progress through the cavern, kill as many as you can.  Report your results to Evonice Sootsmoker, deeper within the Slag Pit.", completion = "You've done good.  I don't like slavery either.", objectives = "Slay 10 Dark Iron Taskmasters or Dark Iron Slavers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28055] = { id = 28055, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sweet, Horrible Freedom", description = "Of course, we'll want to free as many slaves as we can while we're here.  Most of them will likely join forces with us, anxious to fight against their captors.\n\nHowever, sometimes you will find that slaves are resistant to being freed.  It's a strange phenomenon, often called \"Durnholde Syndrome\".\n\nEither way, you should try to free them.  If they resist, treat them as enemies.  Report your results to Evonice Sootsmoker, deeper within the Slag Pit.", completion = "Strange how so many slaves cope poorly with freedom.  It's a shame to have to do what we do, but such are the truths of war.\n\nNow, we must move on to more pressing tasks.", objectives = "Free 12 Slave Workers. If they resist, kill them.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28056] = { id = 28056, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rise, Obsidion", description = "Overseer Maltorius is in charge here, but he's not the only dwarf of power within the Slag Pit.  Lathoric the Black and his horrifying golem, Obsidion, loom just down this corridor.\n\nInterfering with Lathoric's altar should summon both of them.  Find it, then summon Lathoric and kill him.  Report to Evonice Sootsmoker when you're finished.", completion = "A fight well-fought, {name}!  I'm beginning to feel the tide turn.\n\nNow, when you're ready, let's hit these Dark Irons where it really hurts!", objectives = "Use the Altar of Suntara, then slay Lathoric the Black and Obsidion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28057] = { id = 28057, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kill 'em With Sleep Deprivation", description = "It's a little known fact that dwarves, particularly of the Dark Iron variety, need rest! Lots of rest!\n\nNow I ask you; How can they sleep without pillows?  Exactly, {name}, they can't.  This is why you must steal their pillows.\n\nOnce you've finished your cushion-thievery, talk with Taskmaster Scrange.  He's a bit deeper in the cave, working on a covert project with Hansel.", progress = "What?  Pillows?\n\nWhat?", completion = "I see Evonice is up to her old tricks again.  I guess I'll just... um... hang onto these pillows for a while.\n\nThe important part is that you're here.  We're going to need your help.", objectives = "Obtain 16 Dark Iron Pillows.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28058] = { id = 28058, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Look at the Size of It!", description = "Well, well, well... Isn't this a surprise. The Pillamaster had a gigantic ornate pillow and now it's yours. Evonice Sootsmoker will definitely want to get her grubby little hands all over this item. Take it to her and see if she'll offer you any goodies for your trouble.", progress = "That is one huge pillow! Where'd you get it from?", completion = "This is better than even I could have thought possible! The Chambermaid's magical pillow is mine! You better believe you're going to get a nice reward for this accomplishment, {name}!", objectives = "Take the Pillamaster's Pillow to Evonice Sootsmoker in the Searing Gorge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28059] = { id = 28059, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Claiming The Keep", description = "Have you seen the keep on the north side of the island, {name}?  That is where Keep Lord Farson runs his operation from.\n\nFarson has a small group of dedicated followers and they have been giving us trouble since we got here.  We sent a small group to investigate and they reported back on his exact position within the keep.\n\nCan you finish him off for us?", completion = "You killed him?  We have been trying to take that guy out for weeks!  We thank you, {name}.", objectives = "You have been asked to kill Keep Lord Farson at the Farson Hold. Farson Hold can be found on the north side of the island.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28060] = { id = 28060, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twisted Twilight Ties", description = "Hansel and I came here on a secret mission: kill Overseer Maltorius.  While our main goal still remains the same - defeating Archduke Calcinder - it can't hurt to take out the infamous overseer of the Slag Pit while we're here.\n\nProblem is, Hansel was only prepared to fight one dwarf, but it looks like Maltorius has a visitor... an emissary from the Twilight's Hammer!\n\nSpeak with Hansel and help him out.  Then proceed down this corridor and along the balcony outside to find Overseer Oilfist.", completion = "Twilight's Hammer, eh?  I should've expected as much.  I'm glad you arrived to help them out when you did.\n\nIt looks like, despite all odds, we've pressed our offensive to the doorstep of Calcinder's lair.  It's now time to finish the job.", objectives = "Speak with Hansel Heavyhands and help him assault Overseer Maltorius and Twilight-Lord Arkkus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28061] = { id = 28061, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Minions of Calcinder", description = "There is such a thing as digging too deep, {name}.  While you'll find the richest mineral veins deep below the surface, you'll also find the most evil creatures.\n\nLike fire elementals.\n\nCalcinder's minions roam the cavern ahead.  Every one of them holds a piece of Calcinder's evil within it.  Slay as many as you can, and show no remorse.", objectives = "Slay 6 Searing Flamewraiths.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28062] = { id = 28062, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "From Whence He Came", description = "Archduke Calcinder squirms in the back of this very cavern.  We are close to killing him... but that is not what we are going to do.\n\nSlaying Calcinder here means nothing.  His acolytes can easily revive him.  Instead, we are going to banish him.\n\nI asked you to gather a precious stone from the Twilight's Hammer earlier.  You will now use it against Calcinder.  Engage him, weaken him, then use this device on him.  He will be banished from this realm.\n\nGood luck, brave {name}.", objectives = "Weaken Archduke Calcinder, then use the Sanctified Tripetricine to banish him.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28063] = { id = 28063, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leave No Weapon Behind", description = "Battle supplies are hard to come by on this rock.  Every time we hold off another horde attack, it feels like we are fighting with sticks and stones.\n\nReports have come in that Keep Lord Farson on the north side of the island has a large stockpile of rifles that we could use.  Can you head down there and check it out?\n\nBe careful {name}, Farson's followers will do anything to protect him.", progress = "Any luck with those rifles?", completion = "Thanks for rounding these up for us, {name}.  Kind of hard to fight a battle without any guns.", objectives = "Retrieve 12 Rusty Rifles from Farson Hold on the north side of Tol Barad Peninsula.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28064] = { id = 28064, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welcome to the Brotherhood", description = "You should return to Thorium Point.  Overseer Oilfist and the rest of the Thorium Brotherhood will be wondering how you fared in the fight against Calcinder.", completion = "Our task is complete, and it's all thanks to you, {name}.  I'd like to offer you your choice from our coffers.  In addition, I intend to make you a full-fledged member of our order.\n\nWelcome to the Thorium Brotherhood, {name}.  I'm proud to call you a brother.", objectives = "Report to Overseer Oilfist at Thorium Point in Searing Gorge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28065] = { id = 28065, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Walk A Mile In Their Shoes", description = "We have sent at least 3 different recon groups to investigate Farson Hold in the last few weeks.  Sadly, not one of them has returned back with any info.\n\nAt this point, all we can hope is that they are being held alive as prisoners.  I need you to infiltrate the keep and help get our soldiers back.  This won't be easy {name}, but if anyone can help us, it's you.", completion = "You saved our men!  No words can express our gratitude {name}.", objectives = "Escort a Farson Hold Prisoner to safety. The hold is located on the northwestern tip of the island.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28066] = { id = 28066, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: The Sunken Temple", description = "The Warchief has requested that any able-bodied adventurer head to the Sunken Temple, not far from Stonard, immediately!\n\nThe Atal'ai trolls within are attempting to summon forth Hakkar the Soulflayer! If you so choose, head to the Sunken Temple and speak with the green dragon Lord Itharius, who is prepared to put an end to these dangerous trolls.", sourceObjective = "Speak with Lord Itharius.", sourceObjectiveStatus = "unverified-source-field" }
quests[28067] = { id = 28067, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: The Sunken Temple", description = "King Anduin Wrynn has requested that any able-bodied adventurer head to the Sunken Temple, not far from Marshtide Watch, immediately!\n\nThe Atal'ai trolls within are attempting to summon forth Hakkar the Soulflayer! If you so choose, head to the Sunken Temple and speak with the green dragon Lord Itharius, who is prepared to put an end to these dangerous trolls.", sourceObjective = "Speak with Lord Itharius.", sourceObjectiveStatus = "unverified-source-field" }
quests[28068] = { id = 28068, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Blackrock Depths", description = "King Anduin Wrynn has requested that any able-bodied adventurer head to Blackrock Depths, northwest of Morgan's Vigil, immediately!\n\nThe Dark Iron dwarves pose a serious threat to the citizens of Redridge! If you so choose, head to Blackrock Depths and speak with Morgan, who has returned from her extended absence and wishes to enact her vengeance on the Dark Iron nation.", completion = "You look eager to kill a few hundred Dark Irons in justice's name.\n\nPerfect.", objectives = "Speak with Morgan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28069] = { id = 28069, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Blackrock Depths", description = "The Warchief has requested that any able-bodied adventurer head to Blackrock Depths, west of Flame Crest, immediately!\n\nThe Dark Iron dwarves have already attacked Alliance-held Redridge, and if left unchecked, may soon threaten our few Horde footholds in southern Azeroth.\n\nIf you so choose, head to Blackrock Depths and speak with High Executioner Nuzrak, who is reforming the Kargath Expeditionary Force to finish off the Dark Irons once and for all.", completion = "We've managed to take this small area, but to do anything more we'll need your help.", objectives = "Speak with High Executioner Nuzrak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28070] = { id = 28070, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Blackrock Spire", description = "The Warchief has requested that any able-bodied adventurer head to Blackrock Spire, west of Flame Crest, immediately!\n\nNefarian's armies and Rend Blackhand's followers threaten the very existence of the Horde! If you so choose, head to Blackrock Spire and speak with Acride, our only contact within that may be able to help us stop the impending invasion.", sourceObjective = "Speak with Acride.", sourceObjectiveStatus = "unverified-source-field" }
quests[28071] = { id = 28071, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Blackrock Spire", description = "King Anduin Wrynn has requested that any able-bodied adventurer head to Blackrock Spire, northwest of Morgan's Vigil, immediately!\n\nNefarian's armies and Rend Blackhand's followers threaten the entirety of His Majesty's kingdom! If you so choose, head to Blackrock Spire and speak with Acride, our only contact within that may be able to help us stop the impending invasion.", sourceObjective = "Speak with Acride.", sourceObjectiveStatus = "unverified-source-field" }
quests[28072] = { id = 28072, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Dire Maul Warpwood Quarter", description = "King Anduin Wrynn has requested that any able-bodied adventurer head to Dire Maul's Warpwood Quarter, east of Feathermoon Stronghold, immediately!\n\nAlzzin the Wildshaper has corrupted the area and could take over the entire Maul! If you so choose, head to the Warpwood Quarter and speak with Furgus Warpwood, one of the few uncorrupt beings left inside alive.", sourceObjective = "Speak with Furgus Warpwood.", sourceObjectiveStatus = "unverified-source-field" }
quests[28073] = { id = 28073, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Dire Maul Warpwood Quarter", description = "The Warchief has requested that any able-bodied adventurer head to Dire Maul's Warpwood Quarter, west of Camp Mojache, immediately!\n\nAlzzin the Wildshaper has corrupted the area and could take over the entire Maul! If you so choose, head to the Warpwood Quarter and speak with Furgus Warpwood, one of the few uncorrupt beings left inside alive.", sourceObjective = "Speak with Furgus Warpwood.", sourceObjectiveStatus = "unverified-source-field" }
quests[28074] = { id = 28074, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Dire Maul Capital Gardens", description = "The Warchief has requested that any able-bodied adventurer head to Dire Maul's Capital Gardens, west of Camp Mojache, immediately!\n\nThe fallen Highborne Prince Tortheldrin is using the massive demon Immol'thar to control the area! If you so choose, head to the Capital Gardens and speak with Estulan, a recently discovered pure Highborne seeking to reclaim the fallen city for his people.", sourceObjective = "Speak with Estulan.", sourceObjectiveStatus = "unverified-source-field" }
quests[28075] = { id = 28075, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Dire Maul Capital Gardens", description = "King Anduin Wrynn has requested that any able-bodied adventurer head to Dire Maul's Capital Gardens, east of Feathermoon Stronghold, immediately!\n\nThe fallen Highborne Prince Tortheldrin is using the massive demon Immol'thar to control the area! If you so choose, head to the Capital Gardens and speak with Estulan, a recently discovered pure Highborne seeking to reclaim the fallen city for his people.", sourceObjective = "Speak with Estulan.", sourceObjectiveStatus = "unverified-source-field" }
quests[28076] = { id = 28076, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Northern Dire Maul", description = "King Anduin Wrynn has requested that any able-bodied adventurer head to Northern Dire Maul, east of Feathermoon Stronghold, immediately!\n\nKing Gordok and his growing army of Gordok ogres pose the largest and most powerful threat in the area to us! If you so choose, head to Northern Dire Maul and speak with the Druid of the Talon already sent there as a forward scout.", sourceObjective = "Speak with the Druid of the Talon.", sourceObjectiveStatus = "unverified-source-field" }
quests[28077] = { id = 28077, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Northern Dire Maul", description = "The Warchief has requested that any able-bodied adventurer head to Northern Dire Maul, west of Camp Mojache, immediately!\n\nKing Gordok and his growing army of Gordok ogres pose the largest and most powerful threat in the area to us! If you so choose, head to Northern Dire Maul and speak with the Stonemaul Ogre already sent there as a forward scout.", sourceObjective = "Speak with the Stonemaul Ogre.", sourceObjectiveStatus = "unverified-source-field" }
quests[28078] = { id = 28078, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Stratholme Main Gate", description = "The Warchief has requested that any able-bodied adventurer head to Stratholme's main gate, due north from Plaguewood, immediately!\n\nThe Dreadlord Balnazzar has slain the Scarlet Crusade and resurrected them as the Risen! If you so choose, head to the main gate and speak with Crusade Commander Eligor Dawnbringer, leader of the Argent Crusade effort to retake Stratholme for its true owners.", sourceObjective = "Speak with Crusade Commander Eligor Dawnbringer.", sourceObjectiveStatus = "unverified-source-field" }
quests[28079] = { id = 28079, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Stratholme Main Gate", description = "King Anduin Wrynn has requested that any able-bodied adventurer head to Stratholme's main gate, due north from Plaguewood, immediately!\n\nThe Dreadlord Balnazzar has slain the Scarlet Crusade and resurrected them as the Risen! If you so choose, head to the main gate and speak with Crusade Commander Eligor Dawnbringer, leader of the Argent Crusade effort to retake Stratholme for its true owners.", sourceObjective = "Speak with Crusade Commander Eligor Dawnbringer.", sourceObjectiveStatus = "unverified-source-field" }
quests[28080] = { id = 28080, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Stratholme Service Gate", description = "King Anduin Wrynn has requested that any able-bodied adventurer head to Stratholme's service gate, just northwest of the Northpass Tower, immediately!\n\nLord Aurius Rivendare, former paladin of the Silver Hand and recently resurrected son of none other than Baron Rivendare himself, now leads the remaining scourge forces there! If you so choose, head to the service gate and speak with Crusade Commander Eligor Dawnbringer, leader of the Argent Crusade effort to retake Stratholme for its true owners.", sourceObjective = "Speak with Crusade Commander Eligor Dawnbringer.", sourceObjectiveStatus = "unverified-source-field" }
quests[28081] = { id = 28081, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Stratholme Service Gate", description = "The Warchief has requested that any able-bodied adventurer head to Stratholme's service gate, just northwest of the Northpass Tower, immediately!\n\nLord Aurius Rivendare, former paladin of the Silver Hand and recently resurrected son of none other than Baron Rivendare himself, now leads the remaining scourge forces there! If you so choose, head to the service gate and speak with Crusade Commander Eligor Dawnbringer, leader of the Argent Crusade effort to retake Stratholme for its true owners.", sourceObjective = "Speak with Crusade Commander Eligor Dawnbringer.", sourceObjectiveStatus = "unverified-source-field" }
quests[28082] = { id = 28082, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Scholomance", description = "King Anduin Wrynn has requested that any able-bodied adventurer head to Scholomance, east of Andorhal, immediately!\n\nRecent necromantic activity in the area points to Darkmaster Gandling, and a renewed effort to train powerful sorcerers for the scourge. If you so choose, travel to Scholomance to cleanse this bastion of evil from the Plaguelands.", objectives = "Enter Scholomance.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28083] = { id = 28083, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Scholomance", description = "The Warchief has requested that any able-bodied adventurer head to Scholomance, east of Andorhal, immediately!\n\nRecent necromantic activity in the area points to Darkmaster Gandling, and a renewed effort to train powerful sorcerors for the scourge. If you so choose, travel to Scholomance to cleanse this bastion of evil from the Plaguelands.", objectives = "Enter Scholomance.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28084] = { id = 28084, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Might of the Krom'gar", objectives = "You may now make use of the Krom'gar stockpile, {name}! For a small fee I will sell you armaments of battle, useful for crushing your enemies! The availability of what I sell depends upon your rank in the army. Visit my shop whenever you earn a new rank.\n\nLOK'TAR OGAR!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28085] = { id = 28085, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trouble at Highperch", description = "Thank you for your help, {name}. You should speak with Pao'ka Swiftmountain at Highperch to the southwest.\n\nPerhaps he will know the whereabouts of the Elder Crone?", completion = "I know nothing of the Elder Crone, Magatha. What I do know is that the Twilight's Hammer is destroying Highperch.\n\nWill you help me to stop them, {class}?", objectives = "Speak with Pao'ka Swiftmountain at Highperch in Thousand Needles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28086] = { id = 28086, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Free the Pridelings", description = "The trappers are rounding up all of the young wind riders. {name}, will you go out there and free the pridelings?", completion = "They're precious. One day they'll grow strong, but until then, they must be protected.", objectives = "Free 12 Highperch Pridelings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28087] = { id = 28087, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Death to all Trappers!", description = "There's only one answer for those filthy Twilight's Hammer trappers! Death!\n\nBring me their nets, {name}.", progress = "What insanity could drive someone to do such horrible things?", completion = "There'll be no more trapping this day!", objectives = "Collect 8 Trapper Nets.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28088] = { id = 28088, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Release Heartrazor", description = "The Twilight's Hammer have the alpha male of Highperch pinned down. You must head east up the ramp and release Heartrazor before the pride loses its patriarch!", progress = "You must free Heartrazor before they cart him off to their evil base!", completion = "The great Heartrazor is a majestic creature. He has told me of his gratitude and fondness for you, {name}.", objectives = "Release Heartrazor from all bonds restraining him.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28089] = { id = 28089, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Hillsbrad Foothills!", description = "All able bodied members of the Horde are hereby ordered to report to High Executor Darthalia at Southpoint Gate in Hillsbrad Foothills. The Forsaken war machine marches ever onward, securing Lordaeron for the Horde!\n\nTo reach Southpoint Gate you must follow the road south through Silverpine Forest and take the east fork leading into Hillsbrad Foothills.\n\nOnward, <brother/sister>! Destiny calls!", completion = "I was wondering when reinforcements would show up. Suit up, {name}. It's time to dispense some justice!", objectives = "Report to High Executor Darthalia at Southpoint Gate in Hillsbrad Foothills.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28090] = { id = 28090, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Precious Goods", description = "The gates further down the canyon are shut. Our scouting revealed some kind of stone that they carry in chests in their caravans that they use to open the gates.\n\nGet down there and look for a chest key on the bodies of the guards. When you find it, use it on one of those chests on the caravan wagons and bring the gatestone back to me.", progress = "You know, we could probably just blow the gates, but knowing our demoman, we're probably better off dodging the risk.", completion = "Good going.\n\nDoesn't look like much, does it?", objectives = "Retrieve a Twilight Caravan Gatestone. The Spearwardens should carry keys that can get you into the gatestone chests.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28091] = { id = 28091, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Easy Pickings", description = "The ambush launched smoothly. Most of the guards are dead, but a few are still pinned down with the wagons.\n\nYou can see them just to our west, in the canyon below. Get in there and clear them out so we can get this attack on the move.", completion = "Excellent. Now we can start pushing our ground forces up towards Grim Batol.", objectives = "Kill 8 Twilight Spearwarders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28092] = { id = 28092, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "If The Key Fits", description = "The wyrms have already taken the battle to the sky above Grim Batol. It's up to us to move our men in by ground and secure the gates.\n\nI want you to know what is at stake here, {class}. Grim Batol is the source of Twilight's Hammer reinforcements to all of the highlands. If we do not cut them off here, we will not win the battles ahead.\n\nI'm sending the Gob Squad with you. Get to the gate to the southeast and get it open. Patch should have any further instructions you'll need from there.", progress = "Keep moving. We need to get that gate open.", completion = "Works like a charm, every time.", objectives = "Lead the Gob Squad to the closed Dragonmaw Gate.\n\nIf you lose the Gob Squad, return to Warlord Krogg for reassignment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28093] = { id = 28093, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pressing Forward", description = "Good work so far. We should find the entrance to Grim Batol just past the next gate.\n\nI was ordered to secure the entrance and block off reinforcements while the rest of our men press through the path we've cleared up the canyon. I'm thinking if we get there soon enough, maybe I can let Ticker have a little more fun.\n\nLet's get moving down the canyon to the southwest - we should find the next gate pretty quickly.", progress = "Welcome, {race}.", completion = "The gate is clear. Once your people finish clearing the canyon, we will speak to your leaders about the next move.", objectives = "Bring the Gob Squad past the northern Dragonmaw Gate to the entrance of Grim Batol.\n\nIf you are separated from the Gob Squad, return to Warlord Krogg in Wyrms' Bend to be reassigned.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28094] = { id = 28094, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paving the Way", description = "My orders are to accompany you south through the Dragonmaw Gates towards the entrance of Grim Batol. We're to clear a path so that the rest of the men can follow us up and secure the entrance.\n\nTranslation: kill everything that moves, and don't be ashamed if you have a good time doing it.\n\nThe boys are getting antsy. Let's go.", completion = "We make it look easy.", objectives = "Kill 30 Twilight's Hammer cultists along Wyrm's Bend as you fight towards the entrance to Grim Batol.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28095] = { id = 28095, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breadcrumb Out" }
quests[28096] = { id = 28096, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welcome to the Machine", description = "Come in here dear <boy/girl>, have a cigar. You're gonna go far and fly high as a ranking officer of the Forsaken. Yes, indeed, this is the good life and you are going to live it!\n\nI want you to take these orders and dispense them to the lowly scrubs that come along looking for work. Who you give what to is wholly at your discretion.\n\nWhen you're ready, mount up on my trusty skeletal steed - so they don't miss you - and start living the life! Which means just stand there and wait.", progress = "How's the \"desk job\" coming?", completion = "So how was it? Everything that you dreamed it would be? Exciting, no?\n\nNo?\n\n<Darthalia sighs.>\n\nI can see that you're a true hero. You need action. I guess a \"desk job\" isn't for you.", objectives = "Hand out 3 Quests.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28097] = { id = 28097, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gates of Grim Batol", description = "Kroggs started the assault to push up the canyon. He's just past the gate to our southeast.\n\nI'm going to get the squad together to join the attack. We'll meet you down there.", completion = "The canyon is well fortified, but the distraction that the dragons are providing should be enough to allow us to break through.", objectives = "Speak to Warlord Krogg in Wyrms' Bend.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28098] = { id = 28098, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Twilight Skymaster", description = "Twilight Skymaster Richtofen is at the Twilight Aerie up above and to the southeast. No matter what we do down here, if he's not dealt with, all hope is lost for Highperch.\n\nWhile Heartrazor is too injured to help you with the fight, he can fly you up there. The rest is up to you, {name}.\n\nGood luck.", progress = "{name}, you must take care of Twilight Skymaster Richtofen!", completion = "The pridelings did what? They must love you deeply for freeing them.\n\nThank you, {name}. You've saved Highperch!", objectives = "Get a flight from Heartrazor to the Twilight Aerie and deal with Twilight Skymaster Richtofen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28099] = { id = 28099, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rasha'krak", description = "Based on this information you've delivered, I believe that one of this \"Archduke's\" minions may already have turned its eyes toward Thorium Point.\n\nHis name is Rasha'krak, and he patrols the lava pools just to our south.  He looks like the latent fire elementals that rage nearby, except for one small difference: the bracers of binding that encircle his wrists.\n\nFind him and bring these bracers to me, {name}.  I need proof that we are in danger before we involve ourselves in elemental wars.", progress = "I won't fight any elementals until we have proven that they pose a threat to us.", completion = "It is, unfortunately, as I expected.  These bracers bear the indelible mark of the firelord and his minions.\n\nVery well.  With no Horde or Alliance forces anywhere near this godforsaken gorge, it falls upon the Thorium Brotherhood to stop this Archduke before he spreads any more of his evil.", objectives = "Obtain Rasha'krak's Bracers of Binding.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28100] = { id = 28100, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Talking Totem", description = "The furbolg village to the south is the home of the Deadwood tribe, sworn enemies of the Timbermaw. They are corrupted and foul like so many others, driven mad by the taint of these woods.\n\nSomething unusual has occured near the village though. Travelers coming here have said that the totem next to the road has spoken to them.\n\nI have heard nothing every time I approach it. Perhaps it will speak to you, {name}? Maybe you can find out what's going on for me.", completion = "You... yes, you! I have chosen you, {race}, as my champion! You will do the work of Ruumbo!", objectives = "Speak with the Totem of Ruumbo near Deadwood Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28101] = { id = 28101, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mathias' Command", description = "Recent events make it even more apparent that holing up here and making sporadic attacks on Grim Batol isn't enough to keep our kind safe, much less retake Grim Batol. We need to be more aggressive, we need to strike into their heart.\n\nI've agreed to send dragons to the aid of your commanders. They were already hatching a plan to strike at Grim Batol, so you should focus your attention there first.\n\nYou should be able to find Mathias Shaw in Dragonmaw Pass, in the canyon below us to the south.", completion = "The red dragons have agreed to help! No small feat, I'm sure. You have the thanks of the Alliance.\n\nWe'd already laid out plans for our ambush on a Twilight caravan by the time the dragons contacted us. They're helping by cutting off their retreat.\n\nThe battle still rages. You can definitely be of aid.", objectives = "Speak to Master Mathias Shaw in Dragonmaw Pass.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28102] = { id = 28102, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fight the Power", description = "It's time for the final push against the Jadefire!\n\nIf you're prepared to break through their foul barrier and bring the fight to their leader, I'd also ask your help against the lesser satyr. Our druids fight ferociously, but your strength can help turn the battle.\n\nShow the Jadefire that their power will no longer hold sway over these lands!", completion = "A few of the remaining satyr have fled into the deeper woods, but they have taken heavy losses. Good job, {name}.", objectives = "Slay 8 Jadefire Rogues or Jadefire Shadowstalkers at the Ruins of Constellas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28103] = { id = 28103, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Easy Pickings", description = "The ambush launched smoothly. Most of the guards are dead, but a few are still pinned down with the wagons.\n\nGet in there and clear them out so we can push forward into the canyons.", completion = "Excellent. Now we can start pushing our ground forces up towards Grim Batol.", objectives = "Kill 8 Twilight Spearwardens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28104] = { id = 28104, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Precious Goods", description = "The gates further down the canyon are shut. Our scouting revealed a stone that they carried in chests in their caravans that they used to open the gates.\n\nGet down there and look for a chest key on the bodies of the guards. When you find it, use it on one of those chests on the caravan wagons and bring the gatestone back to me.", progress = "They've grown overconfident. More and more, that seems the downfall of the most powerful armies.", completion = "Good going.\n\nDoesn't look like much, does it?", objectives = "Retrieve a Twilight Caravan Gatestone. The Spearwardens should carry keys that can get you into the gatestone chests.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28105] = { id = 28105, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kavem the Callous", description = "Kavem was cruel enough before the Neferset signed up with Deathwing.  His pleasure in deriving pain now borders on the insane.\n\nIt is he who now holds the keys to our shackles.\n\nHe dwells in the building next to us, to my right.\n\nFind him and take the key from him.  Do not hesitate or show him mercy.  He will slit your throat and think nothing of it.", progress = "You're back.  Do you have the key?", completion = "Excellent, {name}.  We will make our way out of here soon enough.", objectives = "Obtain the Neferset Key from Kavem the Callous.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28106] = { id = 28106, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gates of Grim Batol (DO NOT DELETE, DO NOT DEPRECATE!)" }
quests[28107] = { id = 28107, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paving the Way", description = "My orders are to accompany you south through the Dragonmaw Gates towards the entrance of Grim Batol. We're to clear a path so that the rest of the men can follow us up and secure the entrance.\n\nTranslation: kill everything that moves, and don't be ashamed if you have a good time doing it.\n\nThe boys are getting antsy. Let's go.", completion = "We make it look easy.", objectives = "Kill 30 Twilight's Hammer cultists along Wyrm's Bend as you fight towards the entrance to Grim Batol.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28108] = { id = 28108, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "If The Key Fits", description = "The wyrms have already taken the battle to the sky above Grim Batol. It's up to us to move our men in by ground and secure the gates.\n\nI want you to know what is at stake here, {class}. Grim Batol is the source of Twilight's Hammer reinforcements to all of the highlands. If we do not cut them off here, we will not win the battles ahead.\n\nI'm sending a squad from Highbank with you. Get to the gate to the southeast and get it open. Your lieutenant should have any further instructions you'll need from there.", progress = "Keep moving. We need to get that gate open.", completion = "Like a well-oiled machine.", objectives = "Lead squad from Highbank to the closed Dragonmaw Gate.\n\nIf you lose your squad, return to Master Mathias Shaw for reassignment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28109] = { id = 28109, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pressing Forward", description = "Good work so far.\n\nWe should find the entrance to Grim Batol just past the next gate. I was ordered to secure the entrance and block off reinforcements while the rest of our men press through the path we've cleared up the canyon.\n\nLet's get moving down the canyon to the southwest - we should find the next gate pretty quickly.", progress = "Welcome, {race}.", completion = "The gate is clear. Once your people finish clearing the canyon, we will speak to your leaders about the next move.", objectives = "Bring your squad past the northern Dragonmaw Gate to the entrance of Grim Batol.\n\nIf you are separated from your squad, return to Master Mathias Shaw in Wyrms' Bend to be reassigned.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28110] = { id = 28110, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breadcrumb Out" }
quests[28111] = { id = 28111, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trouble at Azurelode", description = "Productivity from our spider farm at the Azurelode Mine is at a standstill. Captain Keyton has requested that we send help immediately. Keyton claims that the mine spiders refuse command and are running rampant. Furthermore, a group of coastal murlocs are raiding our supplies. I want you to go down there and check things out. Help out Keyton and the spider-handler, {name}.\n\nYou'll find Azurelode Mine to the southeast, near the coast.", completion = "We're in a bit of a bind, {class}. Sarus' spiders are starting to get a little uppity as we've been unable to feed them for days. If we leave the murlocs will overtake our post! Furthermore, Warden Stillwater over at the Sludge Fields is demanding that we send him more humans! He is insatiable! We need help!", objectives = "Report to Captain Keyton at the Azurelode Mine in Hillsbrad Foothills.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28112] = { id = 28112, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Escape From the Lost City", description = "Everything is ready!  Undo my chains and set your friends free.\n\nWe must move quickly before the Neferset scum realize we're up to something!\n\nIf we make it, see my brother, King Phaoris for a reward.", completion = "It is true then?  An outsider rescued Prince Nadun from the Neferset?\n\nWe are truly in your debt, stranger.", objectives = "Free Prince Nadun and speak to King Phaoris at Ramkahen in Uldum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28113] = { id = 28113, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Break the Unbreakable", description = "With the claw, we are ready to break through the Jadefire's defenses.\n\nHead into the ruins to the northwest. Beyond the frontline of the satyr you'll find a narrow pass heading to their corrupted moonwell. An enormous wall of demonic flame bars the path, but the Claw of Tichondrius should be able to dispel it.\n\nBeyond the barrier you will find the leader of these forces, Xavathras, guarding the corrupted moonwell. Slay him once you are through!", progress = "Has Xavathras fallen?", completion = "See what can get done with a little cooperation?\n\nI'll make sure the claw is given to people responsible enough to contain such things... assuming it can't be destroyed.", objectives = "Slay Xavathras.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28114] = { id = 28114, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glorious Harvest", description = "Directly southeast of Southpoint Gate you will find our spider domestication operations. Through the years we have grown a kinship with the spiders of Hillsbrad and have managed to domesticate and breed the adorable little critters. Spiders now serve us as regular household pets and beasts of battle! Such diverse creatures they are!\n\nI need you to head into the fields to the southeast and carefully harvest the eggs that we have incubating on the bears. Deliver the harvest to Sarus at the mine.", progress = "Have you brought my harvest?", completion = "Wonderful! Now to place these eggs into a nice, dark alcove inside the mine and let the miracle of life happen!", objectives = "Recover 60 Creeper Eggs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28115] = { id = 28115, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Past Their Prime", description = "Bears are soulless beasts put upon this earth to torment us. Only through Forsaken ingenuity have we devised a way to make use of the bears so that they may serve some purpose! We use the bears at our spider farm as living egg feeders. Our spiders lay their eggs in the bear flesh and the eggs thrive off of the meat and blood of the beasts.\n\nAfter they have served their purpose the monsters must be put down. Travel southeast and kill the infested bears that have lived past their prime.", completion = "The bear gods are cruel masters. They will continue to populate this world with bears until the end of days. It is our right as civilized people to make use of this nuisance - for the betterment of us all!", objectives = "Kill 8 Infested Bears.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28116] = { id = 28116, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crying Violet", description = "We must prepare carefully before assaulting Jaedenar. The magic of the warlocks and demons within Jaedenar is strong, and we will need wards of our own before entering.\n\nWe need only one more ingredient: Crying Violet, which grows in the hills near the enemy's stronghold to the northwest. \n\nGather the Crying Violet, then meet my assistant in the field. He will know what to do next.", progress = "Have you found the crying violet yet, {name}? We need them quickly.", completion = "Wonderful. Greta chose wisely when she asked you to perform this task. I will work the herbs immediately...", objectives = "Collect 8 Crying Violets.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28117] = { id = 28117, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clearing the Depths", description = "You are a sight for sore eyes, {name}.  Now that we have claimed Tol Barad, the battle has just begun.\n\nWe discovered a cell block just east of here that we need you to clear out.  Turns out that its chock full of ghosts that have been locked up down there for who knows how long.\n\nClear out as much as you can and report back to me when you are done.", completion = "You made it back out alive?  You are a stronger man than I, {name}.", objectives = "You have been asked to kill 9 ghosts of any type in the Cursed Depths, just east of Baradin Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28118] = { id = 28118, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Imprisoned Archmage", description = "We have been trying to clear out the Cursed Depths cellblock since we landed on Tol Barad.  It seems that everytime we get close, that archmage shows up and pushes us back.\n\nNow that we have claimed the island, it's time we take another shot.  Head down there and bring me back his staff as proof that you have finished the job.", progress = "Have you been able to take out the Archmage?", completion = "Galus is dead?  Fantastic work {name}, now we can send down the cleanup crew and get that cellblock ready for new prisoners.", objectives = "You must kill Archmage Galus and return with his Staff from the Cursed Depths, just east of Baradin Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28119] = { id = 28119, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Purity From Corruption", description = "The flowers you brought me were the essential ingredient.\n\nProtective barriers surround Shadow Hold, projected from demonic braziers. If we are to drive the Shadow Council from Felwood, then those braziers must be extinguished.\n\nThis vial has been infused with crying violet and the magic of the wilds. Fill it at the corrupted moonwell in the center of Jaedenar and return to me.", progress = "Do you have the waters from the corrupted moonwell?", completion = "This will do nicely, {name}.", objectives = "Fill the Empty Canteen with water from the corrupted moonwell in the center of Jaedenar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28120] = { id = 28120, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learning From The Past", description = "Now that we finally have a hold on this wretched island, we can start to investigate how it got in this condition.  Some of our troops have discovered journals around the entrance to the Cursed Depths cellblock just east of here.\n\nThese journals are of particular interest to our elder scribes back at base camp.  I need you to recover four of them and bring them back to me as fast as you can.\n\n{name}, be careful down there, that place is crawling with undead.", progress = "Were you able to recover the journals?  Reports mentioned that they were sighted both in and out of the cells down there.", completion = "These journals are in excellent condition {name}.  We will begin deciphering them immediately.  Only time will tell what secrets they hold.", objectives = "You have been asked to recover four Dusty Prison Journals from the Cursed Depths, just east of Baradin Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28121] = { id = 28121, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forces of Jaedenar", description = "The Shadow Council perpetuates the corruption of this land. At Jaedenar in the northwest, they worship the demons of the Burning Legion, and work to open the path for their masters to return to this world.\n\nThe grounds are patrolled by Jaedenar Hounds, Guardians, Adepts, and Cultists - thugs that act as lookout for the more vile forces beneath. They will be the first to die so that these forests may no longer suffer!", completion = "Good, {name}! With their numbers weakened, we can soon begin our assault on their forces deep within Shadow Hold.", objectives = "Slay 12 Jaedenar Forces.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28122] = { id = 28122, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Huge Problem", description = "We finally capture this godforsaken rock and then we find out that there is a huge ettin roaming around, taking out our sentry patrols!\n\n{name}, I need you to round up a few friends and take that ettin down.  We can't have a beast like that roaming around, wreaking havoc.\n\nStay alert, reports from the front say that he is carrying a huge tree as a weapon, and he is not afraid to use it.", completion = "You actually killed him?!  I can't believe it!", objectives = "You have been asked to kill Problim, a giant ettin that roams the paths of Tol Barad.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28123] = { id = 28123, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Demon Chain", description = "Narkrall revealed to me the secret of his influence over the drakes in this area. I thought the Demon Chain was a myth, but he's had it all along.\n\nAnd now the fool is about to lose it!\n\nHis life is meaningless to me but the Dragonmaw can't afford to lose that artifact. Follow him north, up to Thundermar. The city will be in chaos, so you may be able to land undetected. Return to me with the Demon Chain, even if you have to remove it from Narkrall's corpse.\n\nFind that artifact, {name}!", progress = "Do you have it? Yes? The fate of the Dragonmaw depends on the Demon Chain!", completion = "<Zaela takes the gore-spattered length of chain and wraps it around her hand and wrist.>\n\nIf the stories are true, {name}, it was on this length of chain that Deathwing had once fastened the Demon Soul, forged in his bid to control the other dragonflights. The Demon Stone has long been destroyed but perhaps this hunk of elementium holds some residual power...\n\nYou've done a great thing today.", objectives = "Acquire the Demon Chain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28124] = { id = 28124, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On to the Bulwark", description = "{name}, while you and the pridelings were taking care of the skymaster, Lakota Windsong came by. She told me to tell you to meet her east at the Twilight Bulwark.\n\nThat must be where they're holding Magatha Grimtotem.", completion = "I'm glad that you made it.\n\nDon't mind my new clothes. It seemed prudent to blend in.", objectives = "Speak with Lakota Windsong at the Twilight Bulwark in Thousand Needles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28125] = { id = 28125, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Something to Wear", description = "I've got an idea for how you can get close to their leaders without getting killed. But first, you're going to need to find something to wear.\n\nMy suggestion is that you head up there and get their armor from them.", progress = "How much of that armor have you collected?\n\nYou're going to want to be well disguised for the next thing that you're going to have to do.", completion = "<Lakota looks worried about the condition of the armor, especially the bloodstains.>\n\nYou sure don't fool around, do you, {name}? Well, it'll have to do.", objectives = "Collect 10 pieces of Twilight's Hammer Armor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28126] = { id = 28126, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dousing the Flames of Protection", description = "The braziers are spread throughout Shadow Hold.\n\nEnter the tunnel into Shadow Hold, and follow it through the underground passageways. Douse each of the brazier's flames and the protections the Council has set up will fall for at least a short period of time.", completion = "With the Braziers gone, the druids of the Emerald Circle can enter Shadow Hold and clear out the last of the cultists. In time, it may even be used as the barrow den it once was.\n\nYou have my thanks, {name}. Please take this reward.", objectives = "Use the Purified Moonwell Water to douse the four Braziers of Protection within Shadow Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28127] = { id = 28127, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Break Them Out", description = "Magatha's not the only one that the Twilight's Hammer have taken prisoner.\n\nWhile you're up there to the south, you should break as many of them out as you can.", completion = "You give so much of yourself without requiring anything in return.\n\nThe people of Thousand Needles are grateful, as am I.", objectives = "Rescue 5 Bulwark Prisoners from the Twilight Jailers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28128] = { id = 28128, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Inner Circle", description = "With their outer sentries gone, the greater members of the Shadow Council are next.\n\nDeep within the corrupted barrow dens you'll find powerful Jaedenar Warlocks, Hunters, Enforcers, Darkweavers, and Legionnaires.\n\nThey must be defeated if these lands are to be saved!", completion = "The cleansing of Shadow Hold will take much time and effort, but without your defeat of the Shadow Council, it would not be possible at all. Thank you, {name}.", objectives = "Slay 12 defenders inside Shadow Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28129] = { id = 28129, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Demon Prince", description = "The Jadefire satyr that have overrun so much of Felwood work directly with the Shadow Council.\n\nThese satyr answer directly to the ancient and powerful Prince Xavalis. Some say he is the son of Xavius, the first satyr, blessed by Sargeras himself.\n\nWhatever his nature, he must die if we are to scatter the Jadefire and reclaim our barrow dens. Journey deep into Shadow Hold and slay him. Show him no mercy; he will have none for you.", progress = "Xavalis lurks in Shadow Hold in Jaedenar.", completion = "The demons begin to fall! Take heed, {class}. You will find even stronger foes deeper within Shadow Hold.", objectives = "Slay Prince Xavalis.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28130] = { id = 28130, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not The Friendliest Town", description = "Have you been up to Rustberg Village yet {name}?  I would suggest you bring a sharpened blade if you are heading that direction.\n\nThe folks in that town look alright but something suspicious is going on in there.  Reports have been coming in that they are picking off our soldiers left and right.  We have had just about enough of that, so I need you to head down there and do a little cleaning house for us.\n\nTake down as many as you can and report back when you are done.", completion = "Told you that village was full of wackos.  Nice job clearing it out {name}.", objectives = "Commander Marcus Johnson has asked you to kill 14 villagers in Rustberg Village. Rustberg Village is just north of base camp, on the right side.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28131] = { id = 28131, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twin Temptresses", description = "Moora and Salia are the personal servants of Shadow Lord Fel'dan. Do not be deceived by them!\n\nThese foul succubi use their wiles and foul magic to draw mortals deep into Shadow Hold. Those in their grasp undergo brainwashing, or are sacrificed by Fel'dan to his demonic masters.\n\nThe two fight as one and are never found apart, making them a considerable threat. Proceed further into Shadow Hold and slay them.", completion = "Another demonic menace gone. It is time to find their master.", objectives = "Slay Moora and Salia.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28132] = { id = 28132, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Efficient Excavations", description = "This manual describes outlandish theories on how to most efficiently manage large groups of workers as they engage in massive excavation projects.\n\nAfter a quick skim of the material, it becomes clear to you that the author of the book is the figure in charge of the over-aggressive pillagers here.\n\nA map on the back cover indicates that the author has a bunker in the southwest region of Uldum.\n\nPerhaps an introduction is in order.", completion = "Oh look, it's one of little Schnottz's pamphlets.\n\nI'll just be taking that from you, if you don't mind.", objectives = "Bring 'Efficient Excavations' to Belloc Brightblade in Schnottz's Landing.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28133] = { id = 28133, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fury Unbound", description = "Narkrall's drake Torth survived the failed attack on Thundermar, and now the creature is free from his former master.\n\nTorth seeks vengeance against the Dragonmaw, and has already strafed Bloodgulch once. He will keep returning until we skewer him for good. It is time to put the Demon Chain to work.\n\nTorth's old nest is a small cave in the hills west of here that we have turned into a small camp called \"The Gullet.\"\n\nMeet me at the Gullet and we will finish Torth off.", completion = "Once free of the chain, Torth died rather than submit again. I admire the creature. I will have his hide fashioned into a set of armor.\n\nThis much is clear to me now: The Dragonmaw cannot stand alone if the Alliance backs the Wildhammer. Narkrall proved that. And you have proven the might of the Horde, again and again.\n\nI will rebuild our drake wings and take up position outside the Bastion of Twilight. You should continue to help out here in the Gullet and elsewhere in the Highlands.", objectives = "Travel to the Gullet and speak with Zaela. Kill Torth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28134] = { id = 28134, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Impending Retribution", description = "Now that you've been suitably rewarded, I hope I can speak with you frankly.\n\nYou've done my kingdom a great favor, but you've also unbalanced a fragile peace process.\n\nI was pursuing my brother's release strictly through diplomatic means in order to avoid bloodshed.\n\nNow, the enemy is sure to seek retaliation.\n\nSpeak to Nomarch Teneth at the Tahret Grounds to the east, Sun Priest Asaris at the Seal of the Sun King to the north and Asaq at Mar'at to the west.  Find out where the enemy will strike.", completion = "Orsis!  Of course!\n\nHow could I not have seen this?", objectives = "Speak to Nomarch Teneth at the Tahret Grounds, Sun Priest Asaris at the Seal of the Sun King, and Asaq at Mar'at.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28135] = { id = 28135, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Al'Akir's Vengeance", description = "Listen, {name}.  What struck Orsis was no natural sandstorm.  It was the minions of Al'Akir.\n\nThe elemental lord of air is firmly allied with Deathwing and it was only a matter of time before he set his subjects upon my people.\n\nOrsis has been attacked as a warning to us.  We must move quickly to offer our brethren what aid we can.\n\nMeet with Nadun at the Arsad Trade Post outside of Mar'at.  I will begin preparations to take care of the displaced and wounded.", completion = "Do you see what Deathwing's minions have done?  Great Orsis is now all but buried in the sand!", objectives = "Speak to Prince Nadun at the Arsad Trade Post outside Mar'at in Uldum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28136] = { id = 28136, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Behind You!", description = "The three leaders of the Bulwark are powerful and not to be underestimated, {name}. Fortunately for us, you now have a disguise to make you look like one of the Twilight cultists.\n\nYou should put the disguise on and speak with Codemaster Deethuk, Commander Fastfuse, and Elementalist Starion each alone. Get them to turn their backs on you, and when they do, strike quickly!", completion = "Now that those three are dealt with, the combined forces from Freewind Post should be able to handle the rest of the cultists here.", objectives = "Assassinate Codemaster Deethuk, Commander Fastfuse, and Elementalist Starion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28137] = { id = 28137, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teach A Man To Fish.... Or Steal", description = "Rustberg Village.  That place is a curse and a blessing for us, {name}.  I have no clue where bandits learned to fish as well as they do but I have no time to worry about that now.\n\nI need you to head down there and steal as many of their fish reserves as possible.  We have been living off scraps since we retook the island and this is our best chance at some solid food reserves.\n\nKeep an eye out for stealthers up there, reports have told us they are prevalent inside the village walls.", progress = "Were you able to pull off the heist and get us some fish?", completion = "These fish will do nicely, {name}.  Keeping the troops fed and in good condition is our number one priority and you really came through for us here.", objectives = "You must steal 22 Rustberg Seabass from Rustberg Village. The fish can be found on string stands at the docks, round back of the village. Rustberg Village is due north of base camp, on the right side.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28138] = { id = 28138, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Human Infestation", description = "This mine was once the heart of Alliance mining operations in Hillsbrad. It now serves as a breeding ground for our loyal spiders, though, the humans still occupy it - in a way.\n\n<Keyton grins.>\n\nBut onto business! Warden Stillwater has called for more workers at the Sludge Fields. I want you to enter the mine with these shackles and capture Hillsbrad humans for labor in the fields.\n\nBreak them out of their web paralysis and beat them into submission before you use the shackles.", progress = "We mustn't keep the warden waiting!", completion = "These will do nicely. I do wonder what the warden has planned for them. Last I heard the Sludge Fields were overrun by some very bad things.", objectives = "Capture 8 Hillsbrad Humans.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28139] = { id = 28139, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Codemaster's Code", description = "{name}, the bonds holding Magatha are specially encoded. She can only be released if we get those codes.\n\nThere's a device near Codemaster Deethuk in the Bulwark to the southeast. It contains the codes.\n\nPlease obtain them.", progress = "Do you have the codes to the Elder Crone's bonds?", completion = "Good. Now there's only one thing left to do.", objectives = "Obtain the Codemaster's Code.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28140] = { id = 28140, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Elder Crone", description = "You have the code. Now all you have to do is head to the eastern section of the Bulwark and free the Elder Crone.\n\nGood luck, {name}. Thank you for all you've done.", objectives = "Disable Magatha's Bonds Controller.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28141] = { id = 28141, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relics of the Sun King", description = "The Seal of the Sun King serves as a defense mechanism for Ramkahen.\n\nWhen the barrier around Uldum fell, we began to see Wastewander outriders from Tanaris filter into our borders.\n\nThey attacked this holy site on their way west and robbed it of the relics which once provided its power.\n\nRecover the relics for us.  Without them we are powerless to defend against attacks from the desert.", progress = "Did you succeed?", completion = "Thank you.  The rumors I'd heard about you are proving true after all.", objectives = "Obtain 4 Relics of the Sun King.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28142] = { id = 28142, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Withering", description = "According to Magatha, she'll meet you just outside of the Twilight Withering to the east.", completion = "It took you long enough. Do you think that we are playing games here?", objectives = "Speak with Magatha Grimtotem at the Twilight Withering in Thousand Needles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28143] = { id = 28143, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Withering", description = "You should not keep the Elder Crone waiting, {name}.\n\nShe said that she'd be up top and just outside of the Twilight Withering to the east.", sourceObjective = "Speak with Magatha Grimtotem at the Twilight Withering in Thousand Needles.", sourceObjectiveStatus = "unverified-source-field" }
quests[28144] = { id = 28144, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thieving Little Monsters!", description = "The long stretch of coastline directly south of our position that extends from west to east is known as the Western Strand. Along the Western Strand you will find two things: murlocs and our stolen \"supplies.\"\n\n<Keyton puts his hands in the air and makes quotation marks with his fingers.>\n\nThose damned thieving murlocs struck while our backs were turned and took our \"supplies.\"\n\nSarus and I cannot leave this post. We need you to head to the Western Strand and recover those \"supplies!\"", progress = "Recover our \"supplies,\" {name}!", completion = "At least we'll be prepared for any future incidents. Moving \"supplies\" like this around is a risky proposition. You never know who is going to open their big fat mouth.\n\n<Keyton raises what appears to be an eyebrow at you.>", objectives = "Recover 6 Forsaken Camp \"Supplies.\"", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28145] = { id = 28145, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Venomblood Antidote", description = "Iset attempted to defend this holy ground when the Wastewander bandits ransacked it.\n\nThey appear to have used the potent toxin present in the venomblood scorpids.\n\nTake this vial and collect venom from their corpses so that I may concoct an antidote.  I fear Iset might not have much time.", completion = "Thank you, {name}.  We might yet save Iset.", objectives = "Fill the Antidote Vial with the poison of 8 Venomblood Scorpid corpses.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28146] = { id = 28146, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Coastal Delicacies!", description = "My spiders are hungry and agitated! They haven't eaten for days and are starting to sample our human captives. We can't have that. We need those humans for use in the Sludge Fields.\n\nI want you to take one of my hungry mine spiders out and feed it murlocs from the Western Strand, south of here. Whatever you kill, it'll eat! The more the better!", completion = "This should keep it happy and content for a few days. You've done a good thing here, {name}!", objectives = "Feed the Hungry Mine Spider 12 Murlocs from the Western Strand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28147] = { id = 28147, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Purple is Your Color", description = "So far as I can tell, the Glopgut Ogres right outside the cave here have not yet joined up with the Twilight's Hammer. If we're clever, we can turn the two groups against each other.\n\nLet's roll with a little trick I learned in Silithus. First we'll need to put together a set of cultist robes for you.\n\nHead south of here and kill some Twilight Windwarpers in the Twilight Breach. Aside from disrupting whatever they're up to, it'll give you a chance to collect garment scraps.", progress = "This is good, {name}. With heroes like you stirring up trouble out here, we'll keep the cult distracted from our main invasion.\n\nDo you have a disguise?", completion = "What did you manage to get? I suppose we can piece something together from this.\n\nAfter all, you're not joining the cult. We just need to fool a few ogres.", objectives = "Gather up 8 Twilight Garment Scraps.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28148] = { id = 28148, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Culling the Corrupted", description = "The sickening corruption of demons pervades this entire forest. The soil, the trees, the animals... all grow thick with fel magics.\n\nWe of the Emerald Circle have sworn to cleanse this forest, and doing so requires a constant battle. While some life here can still be healed, the bears and wolves that wander nearby have been twisted too far.\n\nWe must end their suffering, and ensure their bodies do not spread the taint further. Hunt the bears and wolves, and return to me with their hides.", progress = "I must have the pelts to purge them of the leftover demon essence.", completion = "I will see these are burned swiftly and safely, {name}. You have my thanks.", objectives = "Collect 10 Corrupted Pelts from Angerclaw Bears or Felpaw Wolves.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28149] = { id = 28149, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Whispers in the Wind", description = "You hear dem, {class}? De voices from de cave. Dey want to talk, but dey ain't got no breath.\n\nLet's find a way to listen. De Twilight's Hammer, dey talk to de wind. Go to de Twilight Breach south of here, and grab de Windspeaker Charm from de camp. It'll be atop a stone pillar.\n\nWe'll need us de breath of the elementals, too! Slay de Storm Vortexes and take what joo need.", progress = "Shhh, {name}! Listen. Listen...", completion = "Dat's de stuff, mon!\n\nNow can you hear dem? De spirits, dey be talkin', but dey say nothing nice.\n\nLet us bring dem to de light.", objectives = "Collect a Windspeaker charm and 5 Breath of the Vortex.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28150] = { id = 28150, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Arcane Ally", description = "The Emerald Circle is sworn to accept the help of any who wish to fight the demons of Felwood. Though my people have long shunned the arcane, we cannot afford to deny ourselves such advantage here.\n\nArcanist Delaris, a surviving Highborne mage, helps us battle the Jadefire satyr. Follow the road to the north, and you will find her at our encampment overlooking the Ruins of Constellas.\n\nIf you wish to help cleanse Felwood, follow her requests as you have mine.", completion = "There is little time for talk, {class}. The druids fight valiantly against the satyr, but fel sorcery blocks their path.\n\nLuckily, I have a plan...", objectives = "Speak with Arcanist Delaris at the Ruins of Constellas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28151] = { id = 28151, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dressed to Kill", description = "Your disguise is ready, {name}. Whenever you go north into Glopgut's Hollow now, your Twilight's Hammer regalia will fool the ogres.\n\nThe rest of the plan is simple: you kill a bunch of Glopgut ogres, and they blame the cult. Are you ready to create some havoc in the ogre camp? I thought so.", completion = "Hah! I'm sure Twilight's Hammer wanted to number those ogres among their ranks. Now they'll probably have to fight them off instead.\n\nThis is good, {name}. With one well-placed {class} we managed to do the work of a small army. I'll let Warlord Krogg know of your work here!", objectives = "Kill 10 Glopgut Ogres. Your Twilight's Hammer disguise will automatically apply while inside Glopgut's Hollow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28152] = { id = 28152, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jaedenar Awaits", description = "The cultists you saw guarding the claw were members of the Shadow Council, foul warlocks behind nearly every attempt to bring demons into Azeroth.\n\nNorth of here is Jaedenar, named in worship of Kil'Jaeden himself. Deep beneath it stretches Shadow Hold, a former barrow den and the Shadow Council's own stronghold on Azeroth.\n\nTake these herbs north to Wildheart Point, on the east side of the road. Greta Mosshoof will need them for her plan to purify Shadow Hold for good.", progress = "Greetings, {class}. What brings you here?", completion = "Ah, just what I was expecting. With these herbs, our preparations for Jaedenar are nearly ready.", objectives = "Deliver the Arcanist's Herbs to Greta Mosshoof at Wildheart Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28153] = { id = 28153, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadow Lord Fel'dan", description = "Shadow Lord Fel'dan awaits further in the depths, {name}.\n\nHis wrath will be unmatched now that you have slain his beloved pets. Even without Moora and Salia at his side, he is a terrible force to be reckoned with.\n\nBeware his dark powers; he is nearly more demon than orc by now.", completion = "The Shadow Council is broken! One task remains...", objectives = "Slay Shadow Lord Fel'dan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28154] = { id = 28154, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Muckgill's Flipper or Something...", description = "This looks like Muckgill's flipper or something. Maybe there's somebody that cares that you killed this murloc back at the Azurelode Mine camp. Probably not, but it's worth a shot.\n\nTake Muckgill's fin or whatever it might be back to Captain Keyton at the Azurelode Mine in southwestern Hillsbrad.", progress = "Do I look like some kind of murloc scientist?", completion = "Muckgill you say? Never heard of him. What is this anyway? Some kind of fin or something?", objectives = "Deliver Muckgill's Flipper back to Captain Keyton at the Azurelode Mine in Hillsbrad Foothills.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28155] = { id = 28155, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lord Banehollow", description = "Only one final power remains lurking in the depths of Shadow Hold now: Lord Banehollow.\n\nThe Shadow Council here serves his whims, and even Fel'dan was a mere instrument for him to prepare this land for another invasion of the Burning Legion.\n\nProceed carefully, {name}. A dreadlord is a terrifying foe. Stand tall and triumph!", progress = "You have returned. Is everything alright?", completion = "Truly incredible, {name}. To journey within the very lair of evil here and slay every fiend that stands before you... I am overwhelmed.\n\nThe Emerald Circle thanks you for your work here in Felwood. As for Andalar, we will send scouts to rescue him at once. He shall have a hero's welcome.", objectives = "Slay Lord Banehollow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28156] = { id = 28156, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deep Mine Rescue", description = "<You can hear Dumass speaking through the webbing.>\n\nHI! SPIDERS EVERYWHERE! THE CAPTAIN SENT ME TO SAVE THE WORLD AND CAPTURE HUMANS! WHAT IS THIS PLACE ANYWAY? IT'S SO HOT! I...\n\n<Dumass goes on and on about his situation.>\n\nPerhaps you should cut him free and get him back to safety. Or you can just leave him here, though it's your fault that he's stuck in this mine.", progress = "Do I look like some kind of baby sitter?", completion = "Have you ever heard the saying \"survival of the fittest?\" What you're doing conflicts with natural law, buddy! This idiot should have died in the mines. There's no telling what kind of harm he'll cause to himself or another person now that you've saved him from his inevitable demise.\n\nAnd you know who's fault that'll be, right?", objectives = "Escort Dumass to Safety!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28157] = { id = 28157, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Four Twilight Elements", description = "The Twilight's Hammer have summoned a monstrosity. It's a combination of the four elements infused with the power of their special ore, Elementium.\n\nIf you want to save your precious Thousand Needles from total destruction, you're going to have to destroy it. But first, you'll need a few things to get through its protective shielding.\n\nGo east into the Withering and bring back the four Twilight elements.", progress = "Do you have all of the elements, {class}?", completion = "<Magatha gazes at you with naked disdain.>\n\nI'll combine them into a suitable form. I'll keep it's use simple.", objectives = "Collect the four Twilight Elements: Air, Earth, Fire, and Water.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28158] = { id = 28158, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unbound", description = "There are two very powerful elementals that the Twilight's Hammer have bound. They are using the bound Fury and Vortex to infuse Animus with a great deal of power.\n\nWhen Animus has absorbed enough of their power, he will explode. The rest of Thousand Needles and much of the surrounding lands, will be obliterated.", completion = "A simple task for a simple boy. Let us see if you have what it takes to finish the job.", objectives = "Unbind the Bound Fury and the Bound Vortex.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28159] = { id = 28159, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Doomstone", description = "At the core of Animus is an artifact known as the Doomstone. One of its properties is an ability to absorb a great deal of energy.\n\nThis is how the cultists are trying to set off the explosion... by overloading the stone and amplifying the power through the elemental.\n\nBring me the Doomstone. For safe keeping, of course.", progress = "Do you have the Doomstone, {class}?", completion = "Surprising... you lived.\n\nI thank you for doing my dirty work, {class}. You kept my hands clean while ridding me of some incompetent Grimtotem leaders.\n\nNot only do I have the Rattle of Bones, the Writ of History, and the Drums of War, but I now have the ultimate artifact: the Doomstone!", objectives = "Collect the Doomstone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28160] = { id = 28160, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spread the Word", description = "For rendering me faithful service, I grant you your life. Take it and be gone from my sight. Let your people know of all that has transpired.\n\nAnd {name}, if we ever cross paths again, you will die.", completion = "Wow, she's evil! But, what does it mean, {name}? Is Magatha going to destroy us? Is she in charge of the Twilight's Hammer now?\n\nWhatever happens, you've delivered us from our enemies. Please allow me to show you our gratitude.", objectives = "Speak with Fizzle Brassbolts on Fizzle & Pozzik's Speedbarge in Thousand Needles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28161] = { id = 28161, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spread the Word", description = "For rendering me faithful service, I grant you your life. Take it and be gone from my sight. Let your people know of all that has transpired.\n\nAnd {name}, if ever we cross paths again, you will die.", completion = "Wow, she's evil! But, what does it mean, {name}? Is Magatha going to destroy us? Is she in charge of the Twilight's Hammer now?\n\nWhatever happens, you've delivered us from our enemies. Please allow me to show you our gratitude.", objectives = "Speak with Pozzik on Fizzle & Pozzik's Speedbarge in Thousand Needles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28162] = { id = 28162, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Swamp Bait", description = "Supplies are never easy to find in a place like this, {class}.  We have been scouting since we captured the island but things are not looking good.\n\nFortunately, we just  received a scouting report that a swamp full of crocs is just west of our base camp here.  The hides off those crocs will come in handy for our leatherworkers.  Bring back as many as you can.", progress = "You cleared out that swamp yet?", completion = "Looks like you were able to get the croc hides that we needed.  Thanks {name}, your contributions will not go unnoticed.", objectives = "You have been tasked with collecting 8 Crocolisk Hides from the Baradin Crocolisks on Tol Barad. The crocolisks can be found in the swamp, just west of Baradin Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28163] = { id = 28163, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Leftovers", description = "We fought hard to capture this island, {race}.  We cleared out most of the horde scum but I can still smell their foul stench in the air.\n\nI need you to investigate the slagworks, warden's vigil and the ironclad garrison.  Kill any horde that you find.\n\nYou know what they say, the only good horde is a dead horde!", completion = "Those filthy horde never stood a chance.  Nice work, {name}.", objectives = "You have been instructed to kill 12 Horde Infantry on Tol Barad. You can find the holdouts in The Slagworks, Warden's Vigil and the Ironclad Garrison, here on Tol Barad.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28164] = { id = 28164, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Journey to Orgrimmar", description = "A messenger just asked me to pass along an invitation. It is from the priest trainer, Martin Goodchilde, at The Barracks in Orgrimmar.\n\nHe asks that you meet with him at your soonest convenience. The Barracks can be found within the Valley of Honor.", completion = "I'm glad to see you received my message.", objectives = "Speak with Martin Goodchilde at The Barracks in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28165] = { id = 28165, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "D-Block", description = "Have you heard of the D-Block yet {name}?  It's one of the old cellblocks here on the island.  Problem is, it's infested with demons.  We planned on using it to lock up the leftover Horde we found on the island, but that is not going to happen in its current state.\n\nI need you to head down there and clear those demons out.  Report back to me when you are done.", completion = "D-Block is all clear?  Good work, {name}.  We will send down a crew to start cleaning up right away.", objectives = "You have been instructed to kill 10 demons of any type in the D-Block, just northwest of Baradin Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28166] = { id = 28166, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thog's Nightlight", description = "To see de spirits, we need a special light. A light that lights up one's insides. De light of souls.\n\nTwilight's Hammer uses dem to root out traitors after what we did to dem in Hyjal. Dey just gave one to de Glopgut ogres as a gift.\n\nInside de Glopgut Hollow to de north, you'll find de great big brute Thog. He's got him a Light of Souls. At least, he will until you take it from him.", progress = "De light of souls. Does you have it, mon?", completion = "Ah, dis be it, mon.\n\n<The lens glows brightly in Buunu's hands, casting unearthly rays of light across the shadowy cave mouth.>\n\nWe be ready to bring dem spirits out de shadows now.", objectives = "Get the Light of Souls from Glopgut's Hollow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28167] = { id = 28167, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Carvo Blastbolt", description = "I'm going to start preparing my men to leave this place. We can't hold out here any longer. I want you to move to a forward position in the middle of the large room ahead.\n\nYou should find Carvo Blastbolt there. He'll give you further instructions. Good luck, {name}, and I'll see you on the surface.", completion = "Did Nevin send you ahead? That means he's getting ready to end the mission, but there are still survivors to be rescued. We have to help them!", objectives = "Report to Carvo Blastbolt in Gnomeregan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28168] = { id = 28168, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trouble at the Sludge Fields", description = "Warden Stillwater, over at the Sludge Fields, north of here, has sent out a distress signal. The missive wasn't clear, but from what I could make of the letter there's a riot happening at the Sludge Fields and most of the guards have been killed. The warden has warned that any would-be-heroes approach from the back entry, located on the western side of the Sludge Fields.\n\nHe's also asked for discretion. He doesn't want news of this little *ahem* uprising to surface.", completion = "Who are you? Did Sylvanas send you? Everything is FINE! Yes, perfectly fine! I've got it all under control!\n\nWell, fine all things considered that is... We've got a few problems that perhaps you could help with, {class}.", objectives = "Report to Warden Stillwater at the Sludge Fields in Hillsbrad Foothills.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28169] = { id = 28169, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Withdraw to the Loading Room!", description = "Excellent job gathering the other survivors! They - and you - are the reason S.A.F.E. teams keep coming down here. Nevin won't rest until we've found and rescued every possible survivor.\n\nI'm sending my men to the Loading Room to prepare for decontamination. Please follow them and meet up with Gaffer Coilspring when you arrive. She'll set you up for decontamination and have you on your way to the surface.", completion = "It's good to meet you, {class}. We rarely come across survivors as strong and capable as you are. I can help get you decontaminated and on your way out of here.", objectives = "Follow the S.A.F.E. Operatives to Gaffer Coilspring in the Loading Room.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28170] = { id = 28170, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Night Terrors", description = "Me friend Uchek is in de cave already. We set up three shrines inside. All you gotta do is flush out de bad juju from each one, mon.\n\nGo inside de cave here and talk to Uchek. He put you in a trance, put you in de spirit realm. Tread carefully! If you see a ghostly beast, you don't be panicking. Shine de Light of Souls on de beast for a moment or two, and de light will send 'em away for good. De light will keep you safe. Now go cleanse de three shrines!", progress = "Don't fear de darkness, mon.", completion = "You see! De dead be nothing to be scared of. You brought de light to de darkness, mon, and never flinched.\n\nWe can use dis cave now as a base of operations in de northern Highlands. You're de best, {name}!", objectives = "Talk to Uchek in The Gullet. From the spirit realm, use your Light of Souls to keep yourself safe while you visit the three shrines inside the cave.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28171] = { id = 28171, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "And the Sky Streaked Red", description = "With Deathwing otherwise occupied, we have a grim and daunting task ahead of us, under charge of the queen herself. The black dragonflight is to be wiped out.\n\nI would welcome your aid in this, if it is offered. As soon as you are ready, I will send you with the next flight joining the attack.", completion = "It seems you are still with us. I'm somewhat appreciative of that.\n\nThank you.", objectives = "Join the assault on the black dragonflight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28172] = { id = 28172, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Done Nothing Wrong", description = "The Blackrock orcs of the steppes serve a dark master -  one who performs twisted experiments on living creatures to create his own menagerie of abominations.  Many of his test subjects are as corrupted as their master, but others are completely innocent.\n\nIn the whelping downs to the south, they chain baby dragons to the ground, preparing them for such experiments.  I will not stand for this.  Break their fetters and return the hatchlings to me... to safety.", progress = "I hope we weren't too late.", completion = "I will see to it that these dragons are taken care of.", objectives = "Obtain a Freed Red Whelpling, a Freed Green Whelpling, a Freed Blue Whelpling, and a Freed Bronze Whelpling.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28173] = { id = 28173, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blackout", description = "The Twilight Drakehunters used vicious implements to drag our circling drakes from the sky. Hooks that buried into their scales and held the Twilight secure while they brought our kin to the ground.\n\nWe are past the point of peace. Past hope for their redemption. The only mercy we have left to offer the black flight is the oblivion that they so passionately pursue.\n\nUse these hooks to slay the Obsidian Pyrewings to the south. They should allow you much maneuverability in the air if used right.", progress = "Trust me, I know how distasteful it sounds. We have a grim task ahead of us, but tenderness and sympathy must be put aside in these moments... for the sake of all life.", completion = "You seem to have made use of the disturbing implements with ease.\n\nI take solace in knowing that some tools of evil can ultimately still lead to safeguarding life. Nothing is without purpose.", objectives = "Slay 8 Obsidian Pyrewings after using the Wyrmhunter Hooks to reach them.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28174] = { id = 28174, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burning Vengeance", description = "The Blackrock orcs are ceaseless.  They swarm atop the battle-plains to the east, poised to strike at any moment.\n\nThey already attacked my homeland once.  I'm here to make sure it doesn't happen again.\n\nIf you hold any love for mankind, you'll do the same.  So prove yourself.  Travel south, to the Whelping Downs, and slay their whelpers and the hatchling black dragons.  Prove to me that you're ready for this war.", progress = "I suppose you don't have what it takes.\n\nThat's fine.  I can fight this war myself.", completion = "So you're in, then?\n\nGood.", objectives = "Slay 5 Blackrock Whelpers and 5 Flamescale Broodlings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28175] = { id = 28175, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shining Through the Dark", description = "The great petrified tree that lies before us to the south was once a beacon of great life. Our beacon. We lost this forest to the black flight, and it has since been corrupted and petrified. Nearly unredeemable.\n\nBut all is not without hope. I've brought a powerful tool to begin the healing process. The tree may still be saved, with much time and fortune, and with perhaps a little effort from you.\n\nBring this, Alexstrasza's Tear, and use it within the hollowed heart of the tree.", completion = "You've started a wonderful thing this day, amidst all of this blood shed.\n\nIt may take many years, but this ravaged land will be restored. It will be beautiful again.", objectives = "Use Alexstrasza's Tear within the hollow beneath the Obsidian Tree.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28176] = { id = 28176, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Following the Young Home", description = "In the southwestern portion of the Obsidian Forest, you will find some of the black egg clutches. Many of the eggs can be hatched at any time with a bit of prodding from the right flame, and as the whelplings hatch, they will cry out and flock for their mother.\n\nDo not worry, if this purging is to be taken to the whelps, that is not a task that I will force on you. I simply want you to let them out and follow them home as they seek their mother. It is she who we must confront.", completion = "Lirastraza sent me ahead to the lair, suspecting the black dragon we are seeking may still be here. Judging by the hatchlings, it seems she was not mistaken.", objectives = "Use the Mother's Flame on Obsidian Eggs to release whelps. Follow those hatchlings to the lair of their mother.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28177] = { id = 28177, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stocking Up", description = "If we're going to wage war against the Blackrock clan, we're going to need to plan ahead.  My colonel has already put the plan together - now it's time to execute.\n\nI need scorpid stingers... the sharpest ones you can find.  Scorpids are all over the steppes, but you can find most of them in the gulch to the west.\n\nDon't worry about what they're for.  You'll find out soon enough.", progress = "Back already?", completion = "Those scorpids are easy to underestimate.  You're lucky you didn't end up on the end of one of these barbs.  Or maybe you're just good.\n\nI'll add these to the stockpile.  We're not done yet, {race}.", objectives = "Obtain 5 Razor-Sharp Scorpid Barbs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28178] = { id = 28178, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Future Project", description = "We'll need worg hides, and lots of them.  It doesn't matter if they're torn, burned, or bloody, but we need plenty of them.\n\nActually, it's probably better if they're a little beat-up.\n\nYou'll find worgs both to the west and to the east of here.", progress = "Let's take a look at those hides.", completion = "Believe me, {name}... I'm just as anxious to get to the killing as you are.  We've got to keep to the plan.  The armageddon will come soon enough.\n\nI'll keep these hides here.", objectives = "Obtain 11 Ember Worg Hides.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28179] = { id = 28179, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mud Hunter", description = "Hope you're not afraid of getting dirty.  Judging by the looks of you, that won't be a problem.\n\nTo the north, at the lava's edge, you'll find piles of dark mud.  I need it.\n\nIt'd be best if you didn't ask questions, and focused your efforts on following orders, {name}.", progress = "You'll want to watch out for those obsidian elementals.  They have a tendency to sneak up on you.", completion = "This is exactly what we need.\n\nDon't worry, {name}... the orc-killing will come soon enough.", objectives = "Obtain 9 piles of Obsidian-Flecked Mud.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28180] = { id = 28180, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sand, the Cider, and the Orb", description = "Colonel Troteman is waiting for us to the east.  Before we head out though, we need to gather some more stuff.  This time, you'll be taking it from a warlock by the name of Gorzeeki Wildeyes.\n\nYou'll probably find him to the northwest, near the Altar of Storms.  Tell him he's going to help us out.  We need the sand, the cider, and the orb.\n\nHe'll know what it means.", completion = "Gah!  Who are you?\n\nOh, so Keeshan sent you?  Good.  Would ya mind sticking around for a while?  It's nothing big... I just need you to kill some warlocks for me.", objectives = "Speak with Gorzeeki Wildeyes near the Altar of Storms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28181] = { id = 28181, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warlocks Have the Neatest Stuff", description = "Keeshan said he needs supplies?  I've got plenty of supplies!  Problem is, those warlocks have kicked me out of my home, and they're not letting me back in.\n\n<Gorzeeki sizes you up.>\n\nYou might be able to get in, though.  Head north, and grab some of my slumber sand, my fel slider cider, and a clear glass orb.  I'm pretty sure that's what he wants.\n\nOh, and if you happen to accidentally kill any of those orcs while you're up there, I wouldn't be terribly upset.", progress = "Let's see if you managed to get everything.", completion = "I hope that's what Keeshan was looking for.  It's not doing me much good right now, anyhow.", objectives = "Obtain a handful of Slumber Sand, a jug of Fel Slider Cider, and a Clear Glass Orb.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28182] = { id = 28182, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadow Boxing", description = "Ner'gosh the Shadow is the leader of those warlocks to our north.  He's the jerk that kicked me out of my home once those Blackrock orcs started showing up.  Well, they're all jerks, but he's the jerkiest.\n\nIf I'm ever going to move back in near the Altar, Ner'gosh has to go.", completion = "Knowing the way those orcs operate, there'll be another one to take his place soon.  I'll see if I can't sneak back into the altar before that happens.\n\nThanks, buddy.", objectives = "Slay Ner'gosh the Shadow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28183] = { id = 28183, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Keeshan", description = "Well I suppose I'm done with you here.  I'll go shoo those other warlocks out when I build up the courage.\n\nHere, don't forget those supplies.", progress = "It looks like you managed to deal with Gorzeeki.", completion = "<Keeshan looks through the crate.>\n\nGood, good, good.  We can move on.  Our war takes us east, away from Blackrock Mountain... for now.", objectives = "Bring the Warlock's Supplies back to John J. Keeshan at Flamestar Post in Burning Steppes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28184] = { id = 28184, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chiselgrip, the Heart of the Steppes", description = "We're headed to Chiselgrip, right in the center of these steppes.  We'll rendezvous with the Thorium Brotherhood there, as well as with Troteman.\n\nYou familiar with the Brotherhood?  Those dark iron dwarves have helped me out more than once.  We may need their help again.\n\nWe'll pass through Black Tooth Hovel on our way there.  What do you say we kill a few orcs while we travel?  I'm getting a little restless here in this camp.", completion = "You'll have to excuse me, but we're not taking visitors right now.  I'll ask you to leave Chiselgrip out the same door you came in.\n\nOh, Keeshan... is that you?", objectives = "Kill any 15 Blackrock troops on your way to Chiselgrip.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28185] = { id = 28185, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Svarnos", description = "Excellent work on the island capture, {class}.  Now that we have claimed the island, we need to make these cellblocks useable for prisoners.  D-Block has been especially hard to clear out.  Unfortunately it has become overrun with demons of all sorts.\n\nWe have been able to thin out the demons but a large core hound has broken its way out of its cell and is wreaking havoc down there.  I need you to kill him and bring back his collar.", progress = "Is the core hound dead?", completion = "Svarnos is finally dead?  Looks like we can finally get to work setting up that cellblock then.  Thank you {name}.", objectives = "You must kill Svarnos in the D-Block and return with his Cursed Collar. Svarnos can be found in the D-Block, just northwest of Baradin Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28186] = { id = 28186, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cursed Shackles", description = "Have you been down in the D-Block yet, {name}?  Every time we clear that infested cellblock out, the demons seem to return rather quickly.  We learned that they regenerate from the cursed shackles scattered around the area.  That's where you come in to the picture {name}.\n\nI need you to retrieve as many of those shackles as you can and bring them back to me.  We will destroy them immediately.", progress = "Did you find many shackles?  Reports mentioned that they were all over the place down there.", completion = "The shackles!  We will begin the process of destroying these shackles immediately {name}.  Thank you for your help.", objectives = "You have been asked to recover 8 Cursed Shackles from the D-Block, just northwest of Baradin Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28187] = { id = 28187, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missed Me By Zhat Much!", description = "Okay, {race}! Zhis just got real!\n\nSomevone zhinks zhat zhey can get rid of me zhat easily, hmm?\n\nVe shall see about zhat! Nozhink can shtop zhis vork! Nozhink!\n\n<Schnottz looks around at the encroaching flames.>\n\nVe should probably get out of here.\n\nHuury up! Time is vastink!", completion = "It is times like zhese, zhat one learns who his friends really are...", objectives = "Speak to Commander Schnottz when you are ready to accompany him out of the burning building.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28188] = { id = 28188, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prison Revolt", description = "We have the island, now we need to put the resources here to work.  We found an abandoned cellblock just southwest of here and we need you to go check it out {name}.\n\nReports have come back that it is overrun with prisoners that have been stuck down there for years.  Do whatever you need to do to clear that place out.  Report back to me when you are done.", progress = "Were you able to clear out that cellblock {name}?  We are waiting on you.", completion = "You cleared that area out?  Looks like you might be more useful to us that we thought, {race}.", objectives = "You have been instructed to kill 10 prisoners of any type in The Hole, just southwest of Baradin Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28189] = { id = 28189, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Do the Right Thing", description = "You have come upon a horrific scene. Someone or something has buried all of the humans up to their necks in a manner consistent with planting. The ghouls, which are seemingly tending the field of human seedlings, periodically jump to the nearest human and devour its head!\n\nYou can end this right here and now. Take this shovel and \"save\" the humans.\n\nDo the right thing.", objectives = "\"Save\" 15 Human Seedlings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28190] = { id = 28190, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tainted Ooze", description = "This all started with Winna Hazzard. She was a forsaken apothecary at Bloodvenom Post, researching ways to use the demonic ooze here against the Alliance.\n\nWe warned her she was going too far, but she didn't listen, and we did not act fast enough. Now her and everyone at Bloodvenom Post are nothing more than mindless slime creatures...\n\nThe disgusting oozes she used for this still roam near the pools to the east and south. I beg you, {class}, destroy them so that others cannot commit such evil.", progress = "The very thought of those disgusting creatures sickens me! Urgh...", completion = "My rage quells at the news... perhaps I will find it easier to rest and heal now.\n\nMaybe my stomach will settle as well. Urgh...", objectives = "Slay 8 Tainted Oozes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28191] = { id = 28191, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Fitting End", description = "The Obsidian wyrmkin litter the landscape to our south. They're in no position to push back against us, but one can never tell what new threats the ebb of battle may bring.\n\nI want you to take the fight to the wyrmkin. Clear them out so that we may proceed with purging this land of the polluting presence of the black dragonflight.", completion = "You've proven a great ally. I would have never expected such upon our first meeting.", objectives = "Kill 10 Obsidian wyrmkin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28192] = { id = 28192, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No One Here Gets Out Alive", description = "This farm is under lockdown! Nothing gets in and nothing gets out! We're still assessing the situation to try and figure out exactly what happened, but my theory is that the laborers ate the mushrooms and somehow mutated into hideous undead monsters. I mean, how else could this have happened? This is just a farm! We grow mushrooms here! And sludge! Yes, sludge!\n\nTake a look around, {class}, because now that you're here you can't leave until this issue is resolved.\n\nSee for yourself!", completion = "As you can see, they're all monsters! Most of my guards died and the ones that managed to escape are now holding down the barricades, preventing any of these potentially dangerous creatures from getting out.\n\nWe need your help!", objectives = "Assess the situation at the Sludge Fields.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28193] = { id = 28193, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lockdown!", description = "Zhat buildink did not explode by itself!\n\nSomevone is tryink to do me in, and you von't rest until I find out who!\n\nShtaht vizh zhe guests. Visit vizh zhem, observe zheir demeanor, and zhen report back to me.\n\nIf zhey know anyzhink at all, I vill haff zhem interrogated!\n\nDismissed!", completion = "Zhey know nozhink, you say?\n\nVery vell, zhen. Zhe search goes on...", objectives = "Commander Schnottz wants you to observe the guests in Schnottz's Landing.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28194] = { id = 28194, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Great Escape", description = "Please, {class}! We need your help!\n\nWe're being kept in this building against our will. And with the commander on such a tirade, there's no telling what he might do to us!\n\nPerhaps if you were to secure some uniforms for us, we could sneak away.\n\nWe never should have come here. I see that now.\n\nIf you help us escape, I will write the TRUTH of what has happened here.\n\nThe men on those ships are all dressed in the garb we need.", progress = "Were you able to find us some uniforms, {race}?", completion = "These are perfect, {class}.\n\nWish us luck!", objectives = "The Prolific Writer in Schnottz's Landing wants you to collect 6 Fresh Uniforms from Schnottz Sea Sailors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28195] = { id = 28195, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sending a Message", description = "I haf eyes and ears in every corner of zhis region, {race}.\n\nI haf heard of zhe murmurings zhat go on amonkst my troops. I haf been most tolerant of zhis pathetic behavior - until now!\n\nI vill send zhe message to everyvone in my ranks, zhat dissension vill not be tolerated!\n\nYou are to exterminate zhe captains aboard my ships in dock. Zhey haf been amonk zhe most disgruntled.\n\nVhen zhis has been done, I vill monitor zhe communications and determine vhat to do next.\n\nDismissed!", completion = "Very good, {race}...", objectives = "Commander Schnottz wants you to kill Captain Margun, Captain Cork, and Captain Kronkh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28196] = { id = 28196, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle for Hillsbrad", description = "The journal documents the last 62 days of Clerk Horrace Whitesteed's life. In it is written damning allegations against Warden Stillwater and his activities at the Sludge Fields.\n\nYou should show this to the warden. He will undoubtedly have an explanation for what is written in this journal.", progress = "What's this?", completion = "<Warden Stillwater flips through the journal, reading under his breath.>\n\nRamblings of a mad man! Clearly he had been ingesting the mushrooms. It is good that you brought this to me, {name}. I will burn it myself!", objectives = "Deliver the Battle for Hillsbrad to Warden Stillwater at the Sludge Fields in Hillsbrad Foothills.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28197] = { id = 28197, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Discretion is Key", description = "We must destroy all of the evidence, {name}! Did I say evidence? I meant crazed undead! Anyway, discretion is key. We must not let the rampaging undead make it out of the Sludge Fields and no one outside of this institution must know about what happened here!\n\nDirectly southeast of here in what used to be the old mushroom farm you'll find a reanimated fiend known as Citizen Wilkes and his cohort, Clerk Horrace Whitesteed. They have been causing huge problems for my guards. Find them and kill them!", progress = "Kill the beasts! We can't have a rampaging geist and skeleton wandering the countryside!", completion = "Well done! Wilkes was hanged after we discovered that he was ingesting mass quantities of mushrooms and other highly toxic substances. After he died he awoke, reborn as an undead geist. Many of my guards fell to Wilkes before he ran off into hiding. Fearing something like this might happen again, we incinerated the Clerk until only bones were left!\n\nWhy would they willingly ingest toxic substances? I have no idea! This is a farm, sir, nothing more!", objectives = "Kill Citizen Wilkes and Clerk Horrace Whitesteed.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28198] = { id = 28198, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Weakest Link", description = "They say a chain is only as strong as its weakest link.\n\nI subscribe to that theory and expand upon it.\n\nRather than removing that weak link, one must... strengthen it.\n\nThe other links will step up their performance out of fear of they themselves becoming the weakest link.\n\nIn my army's case, our weak link has a name.  Salhet.\n\nYou'll find him training near the bottom of those stairs.\n\nStart him off with something easy.  The hyenas on the hills to the west, perhaps.", completion = "It is a great honor to meet you, {name}!  I've heard much about you.", objectives = "Speak to Salhet at the Ramkahen Legion Outpost in Uldum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28199] = { id = 28199, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "For Science!", description = "Samples... yes... must have samples! These, ah, experiments... I mean, these unfortunate laborers must be studied.\n\nTravel southeast to the first farm and kill the risen ghouls. From their decrepit corpses you must recover flesh samples. Bring them to me!\n\n<Arnauld wrings his hands together and laughs maniacally for no discernible reason.>\n\nMust test!", progress = "For science!", completion = "These samples will give us a better understanding of the mindless undead. Take these coins as a reward.", objectives = "Recover 6 Flesh Samples.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28200] = { id = 28200, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Element of Supplies", description = "You'll notice that we're slightly ill prepared for battle.\n\nThe tol'vir tribes had never seen any sort of major confrontation for thousands of years.\n\nAll the combat protocols that the titans programmed into our ancestors are still there, though.  Some are part of our instincts, some get passed on as tradition.\n\nBut none of this can compensate for lack of supplies.  We need weapons.  We need armor.\n\nThe best armor is lined with the skin of the riverbed crocolisks nearby.  Help us gather some.", progress = "I am glad to see you don't think you're above this sort of task.", completion = "Excellent job, {name}.  You might not think this adds up to much, but this might very well be the difference between life and death to one of our soldiers.", objectives = "Collect 20 Hardened Crocolisk Hides.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28201] = { id = 28201, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ploughshares to Swords", description = "We have a sizeable army, but I'm afraid the coming showdown with the Neferset hordes will demand that all able-bodied tol'vir of Ramkahen and Orsis join in the fight.\n\nI want you to be at the forefront of our recruiting efforts.\n\nGo across the river, to the Akhenet Fields, and recruit the laborers that work there.", progress = "You've returned, {name}.  How are the recruitment efforts faring?", completion = "You are a born leader, {name}.  It'll be good to have you by our side when war comes to these lands.", objectives = "Recruit 8 Ramkahen Laborers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28202] = { id = 28202, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Perfect Costume", description = "Judging by your weight, build, and size, we're going to dress you as an orc.  Their army is made mostly of orcs, so you'll fit right in.\n\nDo you know much about tailoring?  If not, then consider this your first lesson.  My crafting table over there has all the necessary supplies on it.\n\nGo ahead and grab whatever you think is necessary, then bring it here.  Thelaron will fix you right up.", completion = "That's it?  That's your disguise?\n\nI'm feeling less confident about our chances.  It was nice knowing you, kid.", objectives = "Bring the appropriate amount of supplies from the Tailoring Table to Thelaron Direneedle at Chiselgrip.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28203] = { id = 28203, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Perfect Costume", description = "Judging by your weight, build, and size, we're going to dress you as an ogre.  The firegut ogres have always worked for the Blackrocks, so you'll fit right in.\n\nDo you know much about tailoring?  If not, then consider this your first lesson.  My crafting table over there has all the necessary supplies on it.\n\nGo ahead and grab whatever you think is necessary, then bring it here.  Thelaron will fix you right up.", completion = "That's it?  That's your disguise?\n\nI'm feeling less confident about our chances.  It was nice knowing you, kid.", objectives = "Bring the appropriate amount of supplies from the Tailoring Table to Thelaron Direneedle at Chiselgrip.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28204] = { id = 28204, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Perfect Costume", description = "Judging by your weight, build, and size, we're going to dress you as a goblin.  The Blackrocks have been known to hire goblin mercenaries to fill their ranks, so you'll fit right in.\n\nDo you know much about tailoring?  If not, then consider this your first lesson.  My crafting table over there has all the necessary supplies on it.\n\nGo ahead and grab whatever you think is necessary, then bring it here.  Thelaron will fix you right up.", completion = "That's it?  That's your disguise?\n\nI'm feeling less confident about our chances.  It was nice knowing you, kid.", objectives = "Bring the appropriate amount of supplies from the Tailoring Table to Thelaron Direneedle at Chiselgrip.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28205] = { id = 28205, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Perfect Costume", description = "Judging by your weight, build, and size, we're going to dress you as a troll.  The Smolderthorn trolls have always worked with the Blackrock orcs, so you'll fit right in.\n\nDo you know much about tailoring?  If not, then consider this your first lesson.  My crafting table over there has all the necessary supplies on it.\n\nGo ahead and grab whatever you think is necessary, then bring it here.  Thelaron will fix you right up.", completion = "That's it?  That's your disguise?\n\nI'm feeling less confident about our chances.  It was nice knowing you, kid.", objectives = "Bring the appropriate amount of supplies from the Tailoring Table to Thelaron Direneedle at Chiselgrip.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28206] = { id = 28206, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Lost Lad", description = "It was only yesterday that I sent him out to investigate the farm directly east of here, but it feels like an eternity has passed!\n\nTrue perfection. The way his blond locks framed his perfect blood elf face... Such strength. I didn't want to send him away, but he insisted! How could I refuse him?\n\nAlas, poor Johnny Awesome has not returned! I fear the worst, {name}. Find him!", completion = "<Johnny is sobbing loudly.>\n\nTw... Twinkles!!!! Th... It killed her!\n\n<Johnny continues to cry. Little snot bubbles form in his nostrils.>", objectives = "Find Johnny Awesome at the Sludge Fields in Hillsbrad Foothills.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28207] = { id = 28207, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Slimy Situation", description = "This poor fellow here barely escaped Bloodvenom Post with his life! If we're going to keep him from turning into a slime creature like all the others, we've got to treat the infection.\n\nMushrooms like to grow near the bright green waters around here, like the pond to the east beneath the falls. Most of them are no good... I need you to collect the bright green glowing ones!\n\nIf I have those, I'll be able to whip up something tasty to help this poor tauren. Don't take too long now!", progress = "Remember, it's the bright green glowing ones!", completion = "Most people think the green glow is demonic corruption... but if you've got an eye for shades and hues like me, you can tell it's the energies of the emerald dream! These little guys aren't being corrupted by the waters, they're doing their best to purify it!\n\nNow we'll mash 'em up and make a nice yummy paste for Mr. Tauren to eat and feel all better.", objectives = "Collect 7 Emerald Shimmercaps.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28208] = { id = 28208, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Winna's Kitten", description = "Mr. Tauren here's told me a lot about what happened at Bloodvenom Post. He says Winna Hazzard is still there!\n\nShe's pretty far gone, but what's left of her is making a bunch of new slime. We've got to stop it!\n\nLuckily, I have a plan. Mr. Tauren said Winna used to have a kitten. She fed it corrupted slime water and it ran off into the woods. I saw something lurking to the southeast just past the Bloodvenom Tower, but it sure was bigger than a kitten! Go see if the kitty has a tag...", progress = "Did you find the kitten?", completion = "Poor little kitty, suffering out there in the woods for so long! You did a good thing for it, {name}. And probably for all the travelers it's been eating.\n\nThis tag will be handy...", objectives = "Collect Kitty's Eartag from Winna's Kitten.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28209] = { id = 28209, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freedom for Lydon", description = "This place is no farm! Stillwater has been experimenting on the humans of Hillsbrad. The monstrosities here are all his creations.\n\nThat's not the worst of it, {class}. The aberrations that have the key to my cage are former Forsaken. Stillwater's experiments have the side effect of turning Forsaken into mindless zombies. Why do you think he's so afraid of letting this get out? He knows that such a crime is punishable by true death.\n\nGet me out of here! The infected sludge guards outside have the key!", progress = "Get the key!", completion = "<Lydon takes the key from you.>\n\nI'll let myself out, thanks.\n\nI have never been so angry! Stillwater won't get away with this. I will present his head to the Banshee Queen myself.\n\nYou and I will work together, {name}.\n\nI don't know about the little girl here, but I'd prefer she stayed behind.", objectives = "Recover Lydon's Cage Key.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28210] = { id = 28210, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shaping Up", description = "High Commander Kamses has a special mission for me?\n\nWait... don't tell me.  It's hyenas again, right?\n\nVery well, I shall do my best.\n\nMeet with me at the Sunwatcher's Ridge.\n\nI won't disappoint you.", progress = "What's the tally?", completion = "Well... that wasn't all that great, was it?", objectives = "Help Salhet slay 8 Bloodsnarl Hyenas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28211] = { id = 28211, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tempered in Elemental Flame", description = "First things first: We're going to need ammunition. Ammunition powerful enough to pierce the armored hide of a black drake. \n\nWest of Thundermar is a Wildhammer town that's been overrun with unbound fire elementals. Any weapons left behind in that conflagration will have been tempered in elemental flame. Tougher than anything I could whip up at this forge!\n\nFind me spears in the Humboldt Conflagration, {name}. The pointier the better.", progress = "Spears, yes? My rapid-fire speargun would be rendered ineffective without them.", completion = "Look at that - OW! Pointy! Hot!\n\nThese spears should cut through that dragonhide like an electric cheese-slicing apparatus through butter.", objectives = "Collect 8 Tempered Spears.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28212] = { id = 28212, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hot Stuff", description = "I have a plan to quadruple the recommended torque for a standard speargun of this size, but according to my calculations the act of firing the weapon would shatter the casing. And possibly cleave the planet in two.\n\nI can weld together a chassis 100-times stronger if I had a good source of pure elemental flame for the smelting.\n\nUnbound Emberfiends are roiling around west of here, in the Humboldt Conflagration. Killing them should render them down to pellets of molten fury. Bring me some!", progress = "Do you have the molten fury? No no, don't put it in my hand. Here, use the tongs!", completion = "Marvelous! I'll smelt this down into a delicious soup. An angry soup. Of molten metal.", objectives = "Collect 5 pellets of Molten Fury.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28213] = { id = 28213, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hazzard Disposal", description = "Winna's hooked tight into the source of the slime itself, at the very back of Bloodvenom Post to the west. She makes sure it keeps flowing, and it keeps her safe! But if you can get her attention...\n\nTake the eartag and show it to Winna. If there's even a little, tiny bit of her left, maybe it'll get through. Maybe her regret for her poor lost kitty will come to the surface and she'll feel sorry just one more time, and come out of the slime!\n\nAnd then maybe you can kill her and stop the slime. Yay!", completion = "Hooray! The forest will be safer now!\n\nYou're such a hero, {name}! With everything you've done for me and Mr. Tauren and the trees and animals and flowers, you deserve a reward!\n\nYay!", objectives = "Use Kitty's Eartag to get Winna Hazzard's attention, and then slay her.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28214] = { id = 28214, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cleanup at Bloodvenom Post", description = "Blurgh...\n\nCould you... ugh... could you please... URGH!\n\nExcuse me, I'm still a little... ugh, my stomach. If you're going to Bloodvenom Post to the west, could you please HUUURGH...\n\nJust... just put what's left of my friends out of their misery. Go RIGHT NOW. For your own good. Uuuuurghh...", completion = "Thank you, {class}. I'm feeling much better now, and can appreciate the news that those abominations are gone.\n\nYou still might not want to stand too close, just in case...", objectives = "Slay 6 Bloodvenom Slimeslaves.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28215] = { id = 28215, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Potential Energy", description = "As you well know, the amount of energy stored in a conventional spring is equal to one half the spring's elasticity times the displacement squared. Unless you're using an elementium spring. Then the numbers get obscene! Mathematically grotesque!\n\nI need some elementium loops for my secret weapon, and it just so happens that Twilight's Hammer cultists use coils like that to bind earth elementals.\n\nFind them on the Obsidian Stoneslaves east of here, in the terrible region known as the Black Breach.", progress = "If you start pulling heaps of elementium coils out of your backpack right now, you're going to make me one happy gnome!", completion = "Terrific! These coils will decompress with the force of a thousand suns!\n\nThat's just a rough approximation of course, don't hold me accountable for those numbers.", objectives = "Gather up 10 Twisted Elementium Coils.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28216] = { id = 28216, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magmalord Falthazar", description = "I just heard the terrible news from the west - we've lost Humboldt's Stead. Wiped off the face of the planet in a wall of fire!\n\nThe Twilight's Hammer is to blame, and the survivors say it were the work of one Magmalord Falthazar. He's an ascendant - that's what they call the highest echelon of Twilight's Hammer cultists who become one with the elements. He's a creature of pure fire.\n\nAnd he'll soon be a creature of pure dead! Go kill Falthazar at the Humboldt Conflagration and bring me his head!", progress = "All these years ol' Humboldt throught his worst problems were from the Glopgut ogres up on the ridge. Then the Twilight's Hammer came.\n\nIn an instant, they set the whole valley ablaze like it were a birthday cake. Heartless.", completion = "Aye, that's him. Can you believe this thing was human once?\n\nThat's the Twilight's Hammer for you. What they don't destroy, they corrupt.\n\nThank you, {class}.", objectives = "Collect Magmalord Falthazar's Head.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28217] = { id = 28217, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: The Demon Hunter", description = "Since reclaiming Jadefire Run from the satyr, the Emerald Circle has sent many druids to begin the long task of cleansing the ruins. Last night, several of them were murdered... by a night elf.\n\nThe witnesses say it was a demon hunter, a crazed disciple of Illidan. A rare sight. No doubt he's gone mad with power just like his master.\n\nI'll pay top bounty for proof of this murderer's death. He's been spotted just off the road to the north, in a valley beneath Jadefire Run.", completion = "How noble of you... to blindly kill without question, to come for my head on the barest word of another.\n\nSheathe your fury and hear my tale first. You'll see what noble ignorance has done to these lands.", objectives = "Slay Feronas Sindweller.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28218] = { id = 28218, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Destiny of Flame and Sorrow", description = "My kind has always been hated for what we do... despised outcasts, accused of corruption beyond redemption.\n\nYet if it was not for a demon hunter, these very woods would be the greatest stronghold of the Burning Legion on Azeroth. I speak of my master, Illidan Stormrage, the \"Betrayer\".\n\nSee for yourself. See what occured here when Illidan was first freed, and the demonic forces of the dreadlord Tichondrius ruled this forest completely unopposed...", completion = "And so my master set out to find the skull... risking his own life against an army of demons to find the source of corruption in Felwood. Imagine if he had not! Imagine what these woods would look like if the Skull of Gul'dan had continued its work, undisturbed...", objectives = "Relive Illidan's battle with Arthas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28219] = { id = 28219, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Buzzers for Baby", description = "<The tiny seedling opens its leaves wide, like a baby bird waiting to be fed. It speaks in a very faint voice:>\n\nHungry... want... bugs...<You can hear the buzzing of wasps to the south. Could they be what the little thing wants to feed on?>", completion = "<The seedling pats its stalk with a rooty arm, as if full. It looks to have grown a bit, too!>", objectives = "Kill 10 Ironwood Buzzers to feed the Seedling Protector.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28220] = { id = 28220, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeking Soil", description = "<The tiny sproutling shuffles around, motioning you towards the south. You can barely hear a faint voice.>\n\nSoil...\n\n<It looks like it wants fresh soil. Maybe you should guide it to some of the richer-looking patches.>", completion = "<The seedling coils its roots in what looks like a happy manner.>\n\nGrow... big...", objectives = "Bring the Seedling Protector to 7 patches of Rich Soil.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28221] = { id = 28221, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "These Roots Were Made For Stompin'", description = "There's so many other spirits still trapped in rotting bodies here...\n\nDo you see? The irontree stompers, in the north. They're sick with demon-stuff and icky with mold. Poor spirits inside them can't get out.\n\nYou can help! Chop them down, and the spirits can get out. I'll put the spirits in me and we can all be happy together when I grow up. Will you help? Please?", progress = "Help the poor trees!", completion = "So happy! Can you hear us? We're so many friends now.\n\nBigger and bigger, with room for each friend...", objectives = "Slay 10 Irontree Stompers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28222] = { id = 28222, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Singin' in the Sun", description = "We're growing so much bigger... It's time to shine! Time to spread our leaves to the sun!\n\nTake me to the sun! The sun is far away, but its light comes to us. Its light makes us big and strong again. The light comes down the big branches to the little ones like ours.\n\nOver there! The sun comes to us in the north! Take us with you, take us to dance!", progress = "More sun!", completion = "So warm and fresh and full of life. We love the sun, it makes us stronger.\n\nSoon now, very soon is the time of growing...", objectives = "Guide the Sapling Protector to 5 shafts of sunlight in Irontree Woods.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28223] = { id = 28223, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Warden", description = "We have almost finished clearing out the revolting prisoners in The Hole, but one last problem remains.  The warden.\n\nWarden Silva is their master and they will do anything for him.  If we take him out, we take them all out.  Finish him off and bring me back his keys.  We can use those keys to explore deeper into the cellblock and possibly gain access to the water supply here on the island.", progress = "Is the warden dead yet?", completion = "Ahh, the wardens key's.  Another job well done, {name}.  These will come in very handy.", objectives = "You must kill Warden Silva in The Hole and return with his keys. The Hole is just southwest of Baradin Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28224] = { id = 28224, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Last Protector", description = "Ahhh... thank you, little {race}. I and others have tried so many times to grow in this forest, without success.\n\nThe Withered Protector that lurks in the north is the only ancient to have grown to maturity since the ruining of the forest, but his body is sick and his mind is mad. Just as we gathered the spirits of the treants, I would save those that dwell in him rather than leave them behind.\n\nDefeat him, and let his spirits join me before I set my roots.", progress = "All that is cut will regrow in time; the spirits endure.", completion = "Yes... it is time.", objectives = "Defeat the Withered Protector.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28225] = { id = 28225, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prove Yer Allegiance", description = "Yer welcome to stay in Chiselgrip for a time, but I need to know that yer a friend.  So I've got a task for ye.\n\nWe of the Thorium Brotherhood're not the only dark irons here in the steppes.  Far from it.  We're pretty badly outnumbered by the dark irons of Blackrock Mountain.  We've got a safe enough foothold here in Chiselgrip, but even so, they still pester us from as close as the Ruins of Thaurissan, to the north.\n\nProve yerself, {race}.  Kill 'em for me.", completion = "Now that's what I like to see!  Yer alright, {race}.", objectives = "Kill 10 Dark Iron dwarves in the Ruins of Thaurissan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28226] = { id = 28226, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scrapped Golems", description = "We keep golems here, as guards.  The dwarves to our north also keep golems, but I'm not sure why.\n\nMainly just for killin', I suppose.\n\nWe could use some spare parts for our own golems, so here's what yer gonna do: kill theirs, then look for any parts that might've fallen on the ground.  Salvage what ye can.  Ye probably won't be able to salvage everything, so choose carefully.", progress = "We build these golems ourselves, ye know.  A little mechanical work, a little elemental work... the results aren't half bad, if ye ask me.", completion = "This is exactly what we needed.  I'll get the boys workin' on the next batch of golems right away.", objectives = "Kill War Reavers in the Ruins of Thaurissan, then loot 3 Obsidian Pistons, 3 Flux Exhaust Sieves, 3 Thorium Gearshafts, and 1 Stone Power Core from the War Reaver Parts that they drop.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28227] = { id = 28227, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Golem Training", description = "Yer provin' to be a pretty big help around here, {race}.  I was thinkin ye could help with just one more thing.\n\nOur guards are strong, but they're not as strong as you are.  I was thinkin', maybe if ye wouldn't mind, ye might help some of 'em with their training?  Just go up and talk to one and fight 'em a few times.  Hopefully they'll learn from yer moves and get better.", progress = "Please, help us out, {race}.", completion = "Yer a lifesaver, {name}.  With golems like these, we won't have to worry about Dark Irons, Blackrock orcs... maybe even dragons!\n\nIf ye ever need anything from the Thorium Brotherhood, don't hesitate to ask.  That goes for yer friends, too.", objectives = "Help 4 Chiseled Golems with their combat training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28228] = { id = 28228, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rejoining the Forest", description = "It is time to say goodbye now. You have raised me from a seedling, brief though it was, but now I must rejoin the forest.\n\nTake me back to the hill you found me on. There I will set my roots, and grow in the shadow of the ancients that came before me.", objectives = "Bring the Flourishing Protector back to the hill in the center of Irontree Woods.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28229] = { id = 28229, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nature and Nurture", description = "The ancient protectors of Irontree Woods to the north have been dead for years, their bodies a grim symbol of the damage to these lands.\n\nEvery season, we take the water from this moonwell, and pour it on the ground before them, hoping it will nurture new life. If you'd like, you can deliver the water yourself.\n\nIt is an excellent opportunity for reflection. Take this vial and fill it at the moonwell, and pour it on the very top of the small hill between the three ancients.", objectives = "Fill the vial at the moonwell in Whisperwind Grove and pour it on the ground between the dead ancient protectors in Irontree Woods.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28230] = { id = 28230, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Protocol", description = "Before the warden receives his comeuppance we must deal with the outbreak. We cannot risk this contagion being released into the world.\n\nWithin the laborers' quarters, directly north of here, is a monstrosity Stillwater pieced together out of three farmers. This beast must be destroyed if we are to secure the Sludge Fields! Protocol demands it!", progress = "Do not waste my time, {name}.", completion = "Once we deal with the rest of the undead we will confront Stillwater!", objectives = "Kill the Ray-Getz-Kalaba Monstrosity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28231] = { id = 28231, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Do it for Twinkles", description = "Warden Stillwater sent me out into the field to investigate the outbreak. When I arrived, Twinkles and I were charged by the lumbering monstrosity known as Verringtan. I was knocked off of Twinkles and immediately ran for my life. Twinkles, though, stayed behind and fought the beast off. Alas, she was defeated and then summarily planted in the soil as if she were some type of glorious star pony seedling.\n\nShe gave her life to defend me. Vengeance must be mine! If for nothing else, do it for Twinkles!", progress = "For Twinkles!", completion = "She may now ascend to the great horsey heaven in the stars. We will never forget you, Twinkles. NEVER!", objectives = "Kill the Blacksmith Verringtan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28232] = { id = 28232, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Food From Below", description = "Supplies are running low here in camp, {name}.  We have recently learned that the cellblock just southwest of here has a number of rations remaining from years of use.  We need you to gather as many of those as you can and bring them back to camp.\n\nOne more thing, the entire cellblock is overrun with prisoners so be careful.", progress = "Were you able to recover the rations?  Reports mentioned that they could be found all over the place down there.", completion = "These rations will really help the troops out {name}.  Thank you for your help.", objectives = "You have been asked to recover 12 Cellblock Rations from The Hole, just southwest of Baradin Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28233] = { id = 28233, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lost Brother", description = "Me brother Bahrum has gone missing!\n\nHe was one of the first scouts in the area.  All the others have returned safely, but there be no sign of him.  Da says he's just dawdlin' somewhere, but he's me only brother, and I promised me mum that I would keep him safe.  Will you please find him?", completion = "Don't be looking!  I'm not wearin' me pants!", objectives = "Find Bahrum Forgehammer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28234] = { id = 28234, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They Took Me Pants!", description = "Why I be standing in the grain crate?  Long story short, there were hornets and some Dragonmaw that showed up at a bad time.  I got away safely, but the bastards took off with me legguards!\n\nMy sister made those for me from scratch, even engraved my name on...  I would die of shame if she found out I lost 'em.\n\nPlease find 'em for me - I saw the pant thief going into that fortress over there.  I'm going to stay here for *ahem* cover.\n\nAnd don't be asking what a Wildhammer wears under his kilt!", progress = "Have you found 'em yet?  This grain is pretty itchy.", completion = "Thank you!  Now turn around so I can put'em on.", objectives = "Find Bahrum's legguards.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28235] = { id = 28235, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burnside Must Fall", description = "Magistrate Burnside was once the mayor of this region. In life he was a formidable adversary in the battle over Hillsbrad. In undeath he will surely test us.\n\nBurnside channels great arcane magic in the northwest section of the Sludge Fields. Lead us there and together we shall put an end to his rule, once and for all.", progress = "Do not waste my time, {name}.", completion = "Now to bring Warden Stillwater to justice!", objectives = "Kill Magistrate Burnside.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28236] = { id = 28236, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lost Brother", description = "Me brother Bahrum has gone missing!\n\nHe was one of the first scouts in the area.  All the others have returned safely, but there be no sign of him.  Da says he's just dawdling somewhere, but he's me only brother, and I promised me mum that I would keep him safe.  Will you please find him?", sourceObjective = "Find Bahrum Forgehammer.Me brother Bahrum has gone missing!\n\nHe was one of the first scouts in the area. All the others have returned safely, but there be no sign of him. Da says he's just dawdling somewhere, but he's me only brother, and I promised me mum that I would keep him safe. Will you please find him?", sourceObjectiveStatus = "unverified-source-field" }
quests[28237] = { id = 28237, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Blight Upon the Land", description = "With the undead outbreak contained, the time has come for Stillwater and his followers to answer for their crimes. Though we averted a tragedy the likes of which has not been seen since the Scourge invaded, we must ensure that such a thing can never happen again. They will all face true death!\n\nCome, {name}! I will have Stillwater's head!", progress = "Do not waste my time, {name}.", completion = "I will deliver this head to the Banshee Queen personally. Of course I will make mention of your part in all of this, {name}.\n\nAs for your reward - take from Stillwater's cache whatever you desire. You earned it.", objectives = "Take the Head of Warden Stillwater.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28238] = { id = 28238, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twilight Shores", description = "The time has come, {class}. With Stormwind secure, we will take this fight to the enemy. To the Highlands!\n\nThe bulk of our navy has already shipped out, thanks to your work earlier. But Fargo Flintlocke has prepared a seaplane that can make the journey in double-time.\n\nSpeak with Flintlocke down at the harbor and tell him that you are to accompany him to the Highlands. He will be by the water's edge. Safe journeys, {name}.", completion = "A ride to the Highlands, then? I've just the thing!\n\nI'll make room for yeh in me seaplane. I'll have to ditch the cat-food I was packing, yeh know, in case we crash in the mountains and ain't rescued fer weeks.\n\nOn second thought, jes' keep the cat food on yer lap, aye.", objectives = "Speak with Fargo Flintlocke at Stormwind Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
